-- Biology: 200 hard MCQs (BIO-7001..7200) and 14 syllabus gap MCQs (BIO-7201..7214), 214 questions.
-- Hard set: multi-step reasoning, application and close distractors across every PMDC MDCAT 2025 Biology unit, the
-- NUMS MDCAT 2026 units and the AKU-only chapters. Gap set: topics that the PMDC and NUMS syllabi and PECTAA books leave
-- out but that AKU's official MBBS Biology practice questions test (cell cycle, mitosis and meiosis, cell fractionation,
-- ecological succession, plant tissue culture, algae and lichens); pedigree analysis is in the hard set (BIO-7158, BIO-7159).
-- Original questions in the bank's template. Own id block (7001 up), so the question counter is left alone. Not free.
-- questions.chapter is the MDCAT chapter, or the AKU chapter for questions off the PMDC syllabus (mdcat = 0).
-- NUMS rows only where the NUMS 2026 syllabus names the topic; every question is in the AKU bank; FSc rows only where
-- the PECTAA textbook chapter teaches the topic.

-- Inserted in batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7001', 'Cell structure and function', 'Secretory cells', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'A pancreatic acinar cell secretes large amounts of digestive enzymes. Which pair of organelles would be most extensively developed in it?', '["Rough endoplasmic reticulum and Golgi apparatus", "Smooth endoplasmic reticulum and peroxisomes", "Free ribosomes and lysosomes", "Mitochondria and centrioles"]', 0, 'Secreted proteins are made on ribosomes of the rough ER, then modified, packaged and sent out in vesicles by the Golgi apparatus, so cells that export protein have both in abundance.', '{"1": "Smooth ER makes lipids and steroids and detoxifies drugs; it does not make protein for export.", "2": "Free ribosomes make proteins used inside the cytosol, and lysosomes digest material; neither exports enzymes.", "3": "Mitochondria supply ATP and centrioles organise the spindle, but neither makes or packages secretory protein."}'),
  ('BIO-7002', 'Cell structure and function', 'Secretory pathway', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Cells making a secretory protein are given radioactive amino acids for a few minutes and then followed over time. In which order does the label appear?', '["Golgi apparatus → rough ER → secretory vesicles → outside the cell", "Smooth ER → Golgi apparatus → lysosomes → outside the cell", "Nucleus → rough ER → Golgi apparatus → lysosomes", "Rough ER → Golgi apparatus → secretory vesicles → outside the cell"]', 3, 'Amino acids are built into protein on ribosomes of the rough ER first; the protein then moves in transport vesicles to the Golgi, which packs it into secretory vesicles that fuse with the plasma membrane.', '{"0": "The Golgi receives proteins from the ER; it cannot be labelled before the ER.", "1": "Secretory protein is made on rough, not smooth, ER, and lysosomes are not the export route.", "2": "Proteins are not made in the nucleus, and exported protein ends outside the cell, not in lysosomes."}'),
  ('BIO-7003', 'Cell structure and function', 'Smooth endoplasmic reticulum', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Cells of the adrenal cortex and the interstitial (Leydig) cells of the testis both make steroid hormones. The organelle most abundant in these cells is', '["rough endoplasmic reticulum", "lysosome", "nucleolus", "smooth endoplasmic reticulum"]', 3, 'Steroids are lipids derived from cholesterol, and lipid and steroid synthesis takes place on the smooth ER, which is therefore extensive in steroid-secreting cells.', '{"0": "Rough ER is prominent in cells that secrete protein hormones or enzymes, not steroids.", "1": "Lysosomes digest materials; they do not synthesise hormones.", "2": "The nucleolus makes ribosomal RNA for protein synthesis, which is not the main activity of steroid-making cells."}'),
  ('BIO-7004', 'Cell structure and function', 'Lysosomes', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'In a lysosomal storage disease, one lysosomal hydrolase is missing because of a gene defect. What happens inside the affected cells?', '["Lysosomes burst and release all their enzymes into the cytoplasm", "The undigested substrate of that enzyme accumulates inside enlarged lysosomes", "Protein synthesis on ribosomes stops", "Mitochondria take over the digestion of the substrate"]', 1, 'Lysosomes still form and take in material, but the one substrate that the missing enzyme should break down cannot be digested, so it builds up inside the lysosomes, which swell and damage the cell (as in Tay-Sachs disease).', '{"0": "The lysosome membrane is intact; the problem is a missing enzyme, not rupture.", "2": "Ribosomes and protein synthesis are not directly affected by a missing lysosomal enzyme.", "3": "Mitochondria do not carry out intracellular digestion."}'),
  ('BIO-7005', 'Cell structure and function', 'Fluid mosaic model', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'A mouse cell with fluorescently labelled membrane proteins is fused with a human cell whose membrane proteins carry a different label. Within about 40 minutes the two labels are evenly mixed over the hybrid cell. This shows that', '["membrane proteins are made fresh by both nuclei after fusion", "the membrane is a rigid protein-lipid-protein sandwich", "membrane proteins can move sideways within a fluid lipid bilayer", "the two cells exchange cytoplasm through pores"]', 2, 'Rapid intermixing of the labelled proteins can only happen if they drift laterally in the plane of the membrane, which supports the fluid mosaic model of Singer and Nicolson.', '{"0": "New proteins would not carry the old labels; the labelled proteins already present moved.", "1": "A rigid sandwich (Davson–Danielli) model would not allow proteins to move and mix.", "3": "The result concerns proteins in the membrane, not mixing of cytoplasm."}'),
  ('BIO-7006', 'Cell structure and function', 'Fluid mosaic model', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Fish living in very cold water keep their cell membranes fluid. Compared with fish from warm water, their membrane phospholipids are likely to have', '["more saturated fatty acid tails", "more unsaturated fatty acid tails", "longer, fully saturated fatty acid tails", "fewer phosphate heads per molecule"]', 1, 'Double bonds put kinks in unsaturated fatty acid tails, so the phospholipids cannot pack closely and the membrane stays fluid at low temperature.', '{"0": "Saturated tails pack tightly and make the membrane more rigid in the cold.", "2": "Long saturated tails increase packing and would make the membrane even stiffer.", "3": "Each phospholipid has one phosphate-containing head; the number does not change."}'),
  ('BIO-7007', 'Cell structure and function', 'Prokaryotic and eukaryotic cells', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Some antibiotics kill bacteria by blocking their 70S ribosomes. In high doses these drugs may also harm human cells, mainly by affecting', '["protein synthesis inside mitochondria, whose ribosomes resemble 70S ribosomes", "the 80S ribosomes on the rough endoplasmic reticulum", "the nucleolus, which makes 70S subunits", "the Golgi apparatus, which carries bacterial-type ribosomes"]', 0, 'Mitochondria (and chloroplasts) contain their own small, 70S-type ribosomes, a clue to their bacterial (endosymbiotic) origin, so drugs aimed at 70S ribosomes can interfere with mitochondrial protein synthesis.', '{"1": "Cytoplasmic and rough-ER ribosomes of human cells are 80S, which these drugs do not target.", "2": "The nucleolus makes subunits of 80S cytoplasmic ribosomes, not 70S ones.", "3": "The Golgi apparatus has no ribosomes of its own."}'),
  ('BIO-7008', 'Cell structure and function', 'Prokaryotic and eukaryotic cells', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Which feature is shared by bacteria and chloroplasts and is used as evidence that chloroplasts arose from engulfed prokaryotes?', '["A nucleus bounded by a double membrane", "80S ribosomes", "A circular DNA molecule not associated with histone proteins", "A cell wall made of cellulose"]', 2, 'Like bacteria, chloroplasts and mitochondria have their own naked circular DNA and 70S ribosomes, and divide by fission, which supports the endosymbiont theory.', '{"0": "Neither bacteria nor chloroplasts have a nucleus.", "1": "Both bacteria and chloroplasts have 70S, not 80S, ribosomes.", "3": "Bacterial walls are made of peptidoglycan, and chloroplasts have no wall at all."}'),
  ('BIO-7009', 'Cell structure and function', 'Animal and plant cells', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'A cell has centrioles, no cell wall, several small vacuoles and stores carbohydrate as glycogen granules. It is most likely', '["an animal cell", "a plant mesophyll cell", "a bacterial cell", "a fungal hypha"]', 0, 'Centrioles, absence of a wall, small temporary vacuoles and glycogen storage together identify an animal cell.', '{"1": "Plant cells have a cellulose wall, a large central vacuole and store starch.", "2": "Bacteria have a peptidoglycan wall and no centrioles.", "3": "Fungi store glycogen but have a chitin cell wall."}'),
  ('BIO-7010', 'Cell structure and function', 'Nucleolus', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'A large, prominent nucleolus in a cell most strongly suggests that the cell is', '["about to divide by meiosis", "storing large amounts of lipid", "actively making ribosomes for heavy protein synthesis", "undergoing programmed cell death"]', 2, 'The nucleolus makes ribosomal RNA and assembles ribosomal subunits; cells that make a lot of protein need many ribosomes and so have large nucleoli.', '{"0": "The nucleolus disappears during division; it is not a sign of meiosis.", "1": "Lipid storage is not linked to ribosome production.", "3": "Dying cells shut down synthesis; their nuclei shrink and fragment."}'),
  ('BIO-7011', 'Cell structure and function', 'Mitochondria', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Mature human red blood cells lack mitochondria. They therefore obtain ATP by', '["the Krebs cycle in the cytoplasm", "oxidative phosphorylation using the oxygen they carry", "glycolysis, with pyruvate converted to lactate", "β-oxidation of fatty acids"]', 2, 'Without mitochondria there is no Krebs cycle, electron transport chain or β-oxidation, so red cells rely entirely on anaerobic glycolysis, regenerating NAD⁺ by reducing pyruvate to lactate.', '{"0": "The Krebs cycle runs only in the mitochondrial matrix.", "1": "Oxidative phosphorylation needs the inner mitochondrial membrane; the oxygen in red cells is carried for other tissues.", "3": "β-oxidation also takes place in mitochondria."}'),
  ('BIO-7012', 'Cell structure and function', 'Peroxisomes', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'Which organelle contains oxidase enzymes that produce hydrogen peroxide and also catalase that breaks it down to water and oxygen?', '["Peroxisome", "Lysosome", "Mitochondrion", "Golgi apparatus"]', 0, 'Peroxisomes oxidise substances such as fatty acids and alcohol, producing H₂O₂, and their catalase immediately decomposes the toxic peroxide.', '{"1": "Lysosomes contain acid hydrolases for digestion, not oxidases and catalase.", "2": "Mitochondria carry out aerobic respiration; they are not the site of H₂O₂ breakdown by catalase.", "3": "The Golgi apparatus modifies and packages proteins."}'),
  ('BIO-7013', 'Cell structure and function', 'Cell wall', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'In a woody plant cell, the secondary cell wall is laid down', '["between the primary wall and the plasma membrane", "outside the primary wall, next to the middle lamella", "between the middle lamella and the primary wall", "outside the middle lamella of neighbouring cells"]', 0, 'The middle lamella forms first between cells, then each cell deposits its primary wall inside it; the thick secondary wall is added last, on the inner side of the primary wall next to the plasma membrane.', '{"1": "The secondary wall is deposited by the cell on its inner side, not outside the primary wall.", "2": "The primary wall lies directly against the middle lamella; nothing is inserted between them.", "3": "The middle lamella is the outermost layer shared by neighbouring cells."}'),
  ('BIO-7014', 'Cell structure and function', 'Golgi apparatus', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 3 Cells and subcellular organelles; PMDC MDCAT 2025 Biology 4; NUMS MDCAT 2026 Biology 4', 'The cis face of the Golgi apparatus receives vesicles from the ER, while vesicles leave from the trans face. A drug that blocks vesicle budding from the rough ER would first cause', '["secretory proteins to accumulate in the trans Golgi", "faster release of secretory vesicles", "secretory proteins to accumulate inside the rough ER", "proteins to be made on free ribosomes instead"]', 2, 'If vesicles cannot leave the rough ER, newly made secretory proteins remain trapped in the ER lumen and never reach the Golgi.', '{"0": "Proteins never reach the Golgi, so they cannot accumulate at its trans face.", "1": "Secretion would fall, not rise, because the route out is blocked.", "3": "Blocking ER vesicles does not redirect the signal sequence that sends proteins to the rough ER."}'),
  ('BIO-7015', 'Biological molecules', 'Proteins', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'A protein is made of two separate polypeptide chains containing 250 amino acids in total. How many water molecules were released when its peptide bonds were formed?', '["249", "250", "125", "248"]', 3, 'Each chain of n amino acids has n − 1 peptide bonds. For two chains totalling 250 amino acids, bonds = 250 − 2 = 248, and one water is released per bond.', '{"0": "This treats the protein as a single chain.", "1": "This counts one bond per amino acid.", "2": "This halves the total instead of subtracting one bond per chain."}'),
  ('BIO-7016', 'Biological molecules', 'Carbohydrates', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Hydrolysis of a disaccharide gives two different monosaccharides, one of which is a ketose. The disaccharide is', '["sucrose", "lactose", "maltose", "cellobiose"]', 0, 'Sucrose is glucose (an aldose) joined to fructose (a ketose). Lactose gives glucose and galactose, both aldoses; maltose and cellobiose give two glucose units.', '{"1": "Lactose gives glucose and galactose, which are both aldoses.", "2": "Maltose gives two glucose molecules.", "3": "Cellobiose gives two glucose molecules."}'),
  ('BIO-7017', 'Biological molecules', 'Carbohydrates', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Humans can digest starch but not cellulose, although both are polymers of glucose. This is because cellulose has', '["α-1,4 glycosidic bonds that are too strong for amylase", "β-1,4 glycosidic bonds that human digestive enzymes cannot hydrolyse", "α-1,6 branch points that block amylase", "fructose units in place of glucose"]', 1, 'Cellulose is made of β-glucose units joined by β-1,4 links; human amylase only attacks the α-linkages of starch and glycogen, and humans make no cellulase.', '{"0": "Amylase digests α-1,4 bonds; these are the bonds of starch, not cellulose.", "2": "Cellulose is unbranched; α-1,6 branches occur in amylopectin and glycogen.", "3": "Cellulose is made only of glucose."}'),
  ('BIO-7018', 'Biological molecules', 'Carbohydrates', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Glycogen is more highly branched than amylopectin. The main advantage of this to an animal is that', '["branching makes glycogen more soluble in lipids", "many chain ends allow enzymes to release glucose rapidly when needed", "branching protects glycogen from all hydrolysing enzymes", "branching raises the osmotic pressure of the cell"]', 1, 'Glucose is removed from the ends of chains; heavy branching gives many ends at once, so glycogen can be broken down quickly to meet sudden energy demand, such as in muscle and liver.', '{"0": "Glycogen is a polar carbohydrate; branching does not make it lipid-soluble.", "2": "Branching speeds up rather than prevents enzyme action.", "3": "Storage polysaccharides are useful precisely because they have little osmotic effect."}'),
  ('BIO-7019', 'Biological molecules', 'Water', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Metabolism releases a great deal of heat, yet body temperature changes very little. Which property of water mainly explains this?', '["Its high specific heat capacity, due to hydrogen bonding between molecules", "Its maximum density at 4 °C", "Its ionisation into H⁺ and OH⁻", "Its low viscosity"]', 0, 'Much energy is needed to break hydrogen bonds before water molecules move faster, so water absorbs a lot of heat with only a small temperature rise, buffering body temperature.', '{"1": "Density at 4 °C matters for ice floating, not for absorbing metabolic heat.", "2": "Ionisation affects pH, not heat absorption.", "3": "Viscosity affects flow, not temperature stability."}'),
  ('BIO-7020', 'Biological molecules', 'Lipids', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'When one glycerol molecule combines with three fatty acids to form a triglyceride,', '["three ester bonds form and three water molecules are released", "three glycosidic bonds form and three water molecules are released", "three ester bonds form and two water molecules are released", "three peptide bonds form and three water molecules are released"]', 0, 'Each –OH of glycerol condenses with the –COOH of one fatty acid, forming an ester bond and releasing one water; three fatty acids give three ester bonds and three waters.', '{"1": "Glycosidic bonds join sugars, not glycerol and fatty acids.", "2": "Three condensations release three, not two, water molecules.", "3": "Peptide bonds join amino acids."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7021', 'Biological molecules', 'Lipids', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Phospholipids placed in water spontaneously form a bilayer because each molecule has', '["hydrophilic groups at both ends", "charged fatty acid tails and a non-polar head", "three fatty acid tails attached to glycerol", "a hydrophilic phosphate head and two hydrophobic fatty acid tails"]', 3, 'Being amphipathic, phospholipids arrange their water-loving heads towards water on both faces and hide their water-hating tails inside, forming a bilayer.', '{"0": "A molecule hydrophilic at both ends would simply dissolve.", "1": "The tails are non-polar and the head is polar, not the reverse.", "2": "Three fatty acids make a triglyceride, which forms droplets rather than bilayers."}'),
  ('BIO-7022', 'Biological molecules', 'Proteins', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'An enzyme heated to 80 °C loses its activity permanently. Which bonds in it are NOT broken by this denaturation?', '["Hydrogen bonds", "Peptide bonds", "Ionic bonds", "Hydrophobic interactions"]', 1, 'Denaturation unfolds the secondary, tertiary and quaternary structure by breaking weak bonds, but the covalent peptide bonds of the primary structure stay intact.', '{"0": "Hydrogen bonds hold the helices, sheets and folding and are broken by heat.", "2": "Ionic bonds between side chains are disrupted by heat.", "3": "Hydrophobic interactions that keep the core folded are disrupted when the protein unfolds."}'),
  ('BIO-7023', 'Biological molecules', 'Proteins', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Which protein shows quaternary structure?', '["Haemoglobin", "Myoglobin", "Ribonuclease", "A single α-helix segment of keratin"]', 0, 'Quaternary structure needs two or more polypeptide chains; haemoglobin has four (two α and two β) with their haem groups.', '{"1": "Myoglobin is a single polypeptide chain with one haem group.", "2": "Ribonuclease is a single folded chain (tertiary structure).", "3": "One α-helix is secondary structure."}'),
  ('BIO-7024', 'Biological molecules', 'Carbohydrates', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'Sucrose does not act as a reducing sugar, while maltose does. The reason is that in sucrose', '["glucose is joined to galactose", "the glycosidic bond links the reducing carbons of both glucose and fructose", "there are no free hydroxyl groups at all", "the sugar units are joined by a peptide bond"]', 1, 'In sucrose the bond joins C-1 of glucose to C-2 of fructose, tying up both reducing groups; maltose keeps one free C-1 that can reduce Benedict’s reagent.', '{"0": "Glucose plus galactose is lactose, which is reducing.", "2": "Sucrose has many free –OH groups; it is the reducing carbonyl groups that are blocked.", "3": "Sugars are joined by glycosidic, not peptide, bonds."}'),
  ('BIO-7025', 'Biological molecules', 'Nucleic acids', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'A sample of RNA contains 20% adenine, 30% uracil, 25% guanine and 25% cytosine. Which conclusion is correct?', '["The analysis must be wrong, because A must always equal U", "The molecule must be double-stranded", "The RNA must contain thymine as well", "This is possible, because single-stranded RNA need not have A = U or G = C"]', 3, 'Base-pairing rules (Chargaff’s rules) apply to double-stranded molecules. Most RNA is single-stranded, so its base percentages need not match.', '{"0": "A = U would be required only if the RNA were fully double-stranded.", "1": "If it were double-stranded, A would equal U; here it does not.", "2": "RNA contains uracil instead of thymine."}'),
  ('BIO-7026', 'Biological molecules', 'Nucleic acids', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'A double-stranded DNA molecule contains 18% adenine. What percentage of its bases is cytosine?', '["32%", "18%", "36%", "64%"]', 0, 'A = T = 18%, so A + T = 36%. The remaining 64% is G + C, and G = C, so cytosine = 32%.', '{"1": "18% is the thymine value, which equals adenine.", "2": "36% is A + T together.", "3": "64% is G + C together."}'),
  ('BIO-7027', 'Biological molecules', 'Nucleic acids', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'A DNA segment of 100 base pairs contains 30 adenine–thymine pairs. How many hydrogen bonds hold its two strands together?', '["270", "230", "250", "300"]', 0, 'A–T pairs have 2 hydrogen bonds and G–C pairs 3. 30 × 2 + 70 × 3 = 60 + 210 = 270.', '{"1": "This gives the G–C pairs 2 bonds and the A–T pairs 3.", "2": "This gives every pair 2.5 bonds.", "3": "This gives every pair 3 bonds."}'),
  ('BIO-7028', 'Biological molecules', 'Conjugated molecules', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules; PMDC MDCAT 2025 Biology 3; NUMS MDCAT 2026 Biology 3', 'The ABO blood group antigens on the surface of red blood cells are carbohydrate chains attached to', '["phospholipid heads without any sugar", "cholesterol molecules", "nucleic acids on the cell surface", "lipids and proteins of the membrane (glycolipids and glycoproteins)"]', 3, 'The A and B antigens differ only in the terminal sugar of oligosaccharide chains that are carried on membrane glycolipids and glycoproteins; such conjugated molecules act as cell-recognition markers.', '{"0": "The antigens are defined by their sugar chains.", "1": "Cholesterol does not carry the ABO sugar chains.", "2": "Nucleic acids are not exposed on the red cell surface."}'),
  ('BIO-7029', 'Enzymes', 'Competitive inhibition', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'Malonate inhibits succinate dehydrogenase because its shape resembles succinate. The inhibition can be largely overcome by', '["raising the temperature to 60 °C", "adding more malonate", "raising the concentration of succinate", "lowering the pH sharply"]', 2, 'Malonate is a competitive inhibitor: it competes with succinate for the active site. Adding more substrate makes succinate win most of the collisions, so the rate recovers.', '{"0": "High temperature denatures the enzyme and lowers activity further.", "1": "More inhibitor increases the inhibition.", "3": "Moving away from the optimum pH reduces enzyme activity."}'),
  ('BIO-7030', 'Enzymes', 'Non-competitive inhibition', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'An inhibitor X lowers the rate of an enzyme reaction, and adding a large excess of substrate does not restore the maximum rate. X is most likely', '["a competitive inhibitor that resembles the substrate", "a coenzyme that carries groups to the enzyme", "a non-competitive inhibitor that binds at a site other than the active site", "an activator metal ion"]', 2, 'A non-competitive inhibitor binds elsewhere on the enzyme and changes the shape of the active site, so extra substrate cannot outcompete it and the maximum rate stays low.', '{"0": "Competitive inhibition is overcome by excess substrate.", "1": "A coenzyme helps catalysis rather than lowering the rate.", "3": "Activators increase, not decrease, enzyme activity."}'),
  ('BIO-7031', 'Enzymes', 'Substrate concentration', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'An enzyme reaction is running with substrate in large excess, so that the rate no longer rises when more substrate is added. Which change will increase the rate?', '["Adding more substrate", "Adding a competitive inhibitor", "Cooling the mixture by 10 °C", "Adding more enzyme"]', 3, 'At saturation every active site is busy, so the enzyme concentration is the limiting factor; more enzyme molecules mean more reactions per second.', '{"0": "The active sites are already saturated, so extra substrate has no effect.", "1": "An inhibitor reduces the rate.", "2": "Cooling below the optimum lowers kinetic energy and the rate."}'),
  ('BIO-7032', 'Enzymes', 'Temperature', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'One sample of an enzyme is kept at 5 °C and another at 70 °C; both show little activity. When both are brought to 37 °C,', '["only the sample kept at 70 °C regains activity", "both regain full activity", "only the sample kept at 5 °C regains activity", "neither regains any activity"]', 2, 'Low temperature only slows molecular movement, so the enzyme recovers on warming; at 70 °C the enzyme is denatured and its active site permanently lost.', '{"0": "Denaturation by high temperature is not reversed by cooling.", "1": "The heated enzyme has been denatured.", "3": "Cold does not destroy the active site, so that sample recovers."}'),
  ('BIO-7033', 'Enzymes', 'pH', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'Pepsin works in the stomach but stops working when chyme enters the duodenum mainly because', '["the temperature in the duodenum is much lower", "the pH becomes alkaline, changing the charges on its active site", "amylase digests the pepsin", "all the protein substrate has been used up"]', 1, 'Pepsin has an optimum pH of about 2. Alkaline pancreatic juice and bile raise the pH in the duodenum, altering ionisation of groups in the active site so substrate no longer binds well.', '{"0": "Body temperature is the same in the stomach and duodenum.", "2": "Amylase digests starch, not proteins.", "3": "Much protein remains to be digested by trypsin in the duodenum."}'),
  ('BIO-7034', 'Enzymes', 'Induced fit model', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'Which observation is better explained by the induced fit model than by the lock and key model?', '["Each enzyme acts on only one substrate", "Enzymes are denatured at high temperature", "Competitive inhibitors bind to the active site", "The active site changes shape slightly as the substrate binds, so an enzyme can act on a few related substrates"]', 3, 'Koshland’s induced fit model proposes a flexible active site that moulds around the substrate, which explains broader specificity; the rigid lock and key model explains absolute specificity.', '{"0": "Absolute specificity fits the rigid lock and key model.", "1": "Denaturation is explained by either model.", "2": "Competitive inhibition is explained by either model."}'),
  ('BIO-7035', 'Enzymes', 'Cofactors', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'A solution of an enzyme is dialysed, which removes small molecules, and the enzyme loses its activity. Adding back the dialysed-out fluid restores the activity. The enzyme needs', '["a prosthetic group bound tightly to the protein", "a second protein enzyme", "a higher temperature", "a small, loosely bound cofactor such as a coenzyme or metal ion"]', 3, 'Dialysis removes only small molecules that are not firmly attached. Loss and recovery of activity shows the enzyme needs a dissociable cofactor (coenzyme or activator ion) to form the active holoenzyme.', '{"0": "A tightly bound prosthetic group would stay with the protein during dialysis.", "1": "Proteins are too large to pass out during dialysis.", "2": "Dialysis does not change temperature."}'),
  ('BIO-7036', 'Enzymes', 'Cofactors', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'A non-protein organic group permanently and tightly bound to an enzyme, such as haem in catalase, is called', '["a coenzyme", "a prosthetic group", "an activator", "an apoenzyme"]', 1, 'Prosthetic groups are organic cofactors bound tightly (often covalently) to the protein; coenzymes such as NAD⁺ bind loosely and detach after each reaction.', '{"0": "Coenzymes are loosely attached and move between enzymes.", "2": "Activators are inorganic ions.", "3": "The apoenzyme is the protein part without its cofactor."}'),
  ('BIO-7037', 'Enzymes', 'Activation energy', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'An enzyme is added to a reversible reaction that is already at equilibrium. What happens?', '["More product forms, shifting the equilibrium to the right", "The equilibrium position stays the same, because the enzyme speeds up both directions equally", "More reactant forms, shifting the equilibrium to the left", "The activation energy of the reverse reaction rises"]', 1, 'Enzymes lower the activation energy of the forward and reverse reactions alike, so equilibrium is reached faster but its position is unchanged.', '{"0": "A catalyst cannot change the equilibrium constant.", "2": "A catalyst cannot change the equilibrium constant.", "3": "Enzymes lower activation energy in both directions."}'),
  ('BIO-7038', 'Enzymes', 'Feedback inhibition', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'In the pathway A → B → C → D, each step catalysed by a different enzyme, a build-up of D slows the enzyme that converts A to B. This is', '["competitive inhibition of the last enzyme by A", "feedback inhibition, with D acting as an allosteric (non-competitive) inhibitor", "irreversible inhibition of all enzymes by D", "substrate-level phosphorylation"]', 1, 'The end product binds to a regulatory site of the first enzyme and switches the pathway off, preventing waste; it does not resemble substrate A, so it acts allosterically.', '{"0": "Here the end product inhibits the first enzyme, not A inhibiting the last.", "2": "Feedback inhibition is reversible; it relaxes as D is used up.", "3": "Substrate-level phosphorylation is ATP synthesis, not regulation."}'),
  ('BIO-7039', 'Enzymes', 'Irreversible inhibitors', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'Organophosphate insecticides bind permanently to acetylcholinesterase. The result is that', '["acetylcholine is no longer released from nerve endings", "acetylcholine accumulates at synapses and muscles cannot relax", "nerve impulses cannot start in the axon", "muscles cannot contract at all from the start"]', 1, 'Acetylcholinesterase normally breaks down acetylcholine after each impulse. Blocking it irreversibly leaves acetylcholine in the synaptic cleft, causing continuous stimulation, spasm and paralysis.', '{"0": "Release of acetylcholine is not affected; its breakdown is.", "2": "Axon impulses still occur; the problem is at the synapse.", "3": "Muscles are over-stimulated first, not unable to contract."}'),
  ('BIO-7040', 'Enzymes', 'Substrate concentration', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes; PMDC MDCAT 2025 Biology 6; NUMS MDCAT 2026 Biology 7', 'In a graph of reaction rate against substrate concentration, the curve levels off at high substrate concentration because', '["the substrate has been used up", "all the active sites are occupied at any moment", "the enzyme has been denatured", "the product has stopped forming"]', 1, 'Once every active site is occupied, adding more substrate cannot speed up the reaction; the enzyme is saturated and works at its maximum rate.', '{"0": "There is plenty of substrate at the plateau.", "2": "Concentration does not denature enzymes.", "3": "Product keeps forming, at the maximum rate."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7041', 'Bioenergetics', 'Respiration of fats', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'Gram for gram, fats release about twice as much energy as carbohydrates when respired, mainly because fats', '["are respired completely by anaerobic pathways", "contain phosphate groups that form ATP directly", "contain a much higher proportion of hydrogen, giving more reduced coenzymes for the electron transport chain", "are oxidised entirely in glycolysis"]', 2, 'Fatty acids are long hydrocarbon chains with many C–H bonds and little oxygen; their oxidation yields many NADH and FADH₂ and hence much ATP by oxidative phosphorylation.', '{"0": "Fats can only be respired aerobically.", "1": "Triglycerides have no phosphate groups.", "3": "Fatty acids are oxidised by β-oxidation in mitochondria, not in glycolysis."}'),
  ('BIO-7042', 'Bioenergetics', 'Respiration of fats', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'When a triglyceride is respired, the glycerol part enters the respiratory pathway by being converted into', '["a 3-carbon intermediate of glycolysis (phosphoglyceraldehyde)", "acetyl coenzyme A directly", "oxaloacetate of the Krebs cycle", "fatty acids"]', 0, 'Glycerol is phosphorylated and oxidised to a 3-carbon sugar phosphate (PGAL), which continues through glycolysis; the fatty acids enter as acetyl CoA after β-oxidation.', '{"1": "Acetyl CoA is made from fatty acids by β-oxidation, not from glycerol directly.", "2": "Glycerol does not enter as a Krebs cycle acid.", "3": "Glycerol is not converted to fatty acids for respiration."}'),
  ('BIO-7043', 'Bioenergetics', 'Respiration of proteins', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'Before amino acids can be used as respiratory substrates, they must first undergo', '["β-oxidation", "deamination, the removal of the amino group", "phosphorylation by ATP", "hydrolysis into glycerol"]', 1, 'In the liver the amino group is removed as ammonia (which is turned into urea); the remaining carbon skeleton enters respiration as pyruvate, acetyl CoA or a Krebs cycle intermediate.', '{"0": "β-oxidation is the route for fatty acids.", "2": "Phosphorylation is not the first step for amino acids.", "3": "Glycerol comes from fats, not proteins."}'),
  ('BIO-7044', 'Bioenergetics', 'Respiratory quotient', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'A person’s respiratory quotient (CO₂ released ÷ O₂ used) is found to be about 0.7. The main substrate being respired is', '["fat", "carbohydrate", "protein", "glucose by anaerobic respiration"]', 0, 'Fats are oxygen-poor, so they need more O₂ than the CO₂ they give off, an RQ of about 0.7. Carbohydrate gives 1.0 and protein about 0.8–0.9.', '{"1": "Carbohydrate gives an RQ of 1.0 (equal volumes of CO₂ and O₂).", "2": "Protein gives an RQ of about 0.8–0.9.", "3": "Anaerobic respiration uses no O₂, so the RQ would be very high, not 0.7."}'),
  ('BIO-7045', 'Bioenergetics', 'Aerobic respiration', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'How many molecules of CO₂ are released from one glucose molecule during the link reaction and the Krebs cycle together?', '["4", "2", "6", "3"]', 2, 'Each pyruvate loses one CO₂ in the link reaction (2 per glucose) and each acetyl group loses two CO₂ in the Krebs cycle (4 per glucose): 6 in total, matching the 6 carbons of glucose.', '{"0": "4 counts only the Krebs cycle.", "1": "2 counts only the link reaction.", "3": "3 is the total for one pyruvate, not for glucose."}'),
  ('BIO-7046', 'Bioenergetics', 'Krebs cycle', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'For each glucose molecule, the Krebs cycle itself (not counting the link reaction) produces', '["3 NADH, 1 FADH₂, 1 ATP and 2 CO₂", "6 NADH, 2 FADH₂, 2 ATP and 4 CO₂", "8 NADH, 2 FADH₂, 2 ATP and 6 CO₂", "6 NADH, 2 FADH₂, 4 ATP and 6 CO₂"]', 1, 'One turn gives 3 NADH, 1 FADH₂, 1 ATP (via GTP) and 2 CO₂; one glucose gives two acetyl CoA, so two turns.', '{"0": "These are the products of one turn, that is for one acetyl CoA.", "2": "This adds the 2 NADH and 2 CO₂ of the link reaction.", "3": "The Krebs cycle gives 2 ATP and 4 CO₂ per glucose."}'),
  ('BIO-7047', 'Bioenergetics', 'Electron transport chain', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'Cyanide blocks cytochrome oxidase, the last carrier of the electron transport chain. Which effect follows first?', '["Oxygen consumption by mitochondria increases", "Electrons can no longer pass to oxygen, so oxygen use and ATP synthesis in mitochondria stop", "Glycolysis stops immediately", "The Krebs cycle speeds up"]', 1, 'With the final carrier blocked, the chain backs up, O₂ is not reduced to water and the proton gradient is not maintained; NADH builds up and the Krebs cycle slows too.', '{"0": "Oxygen cannot be used once cytochrome oxidase is blocked.", "2": "Glycolysis can continue anaerobically for a time.", "3": "NAD⁺ is not regenerated, so the Krebs cycle slows."}'),
  ('BIO-7048', 'Bioenergetics', 'Chemiosmosis', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'A chemical makes the inner mitochondrial membrane leaky to H⁺ ions. What happens in the mitochondria?', '["Electron transport stops completely", "Electron transport and oxygen use continue, but little ATP is made and more energy is lost as heat", "ATP production rises because protons move faster", "Oxygen use stops but ATP synthesis continues"]', 1, 'ATP synthase is driven by protons flowing back through it. If H⁺ leaks back through the membrane, the gradient collapses, so oxidation is uncoupled from ATP synthesis and the energy is released as heat.', '{"0": "Electron flow is not blocked; it continues or even speeds up.", "2": "Protons bypass ATP synthase, so less ATP is made.", "3": "Oxygen use continues; it is ATP synthesis that fails."}'),
  ('BIO-7049', 'Bioenergetics', 'Anaerobic respiration', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'During strenuous exercise, muscle cells convert pyruvate to lactate. The main benefit to the cell is that this', '["produces extra ATP from pyruvate", "releases CO₂ that stimulates breathing", "regenerates NAD⁺ so that glycolysis can continue", "stores energy in lactate for later use"]', 2, 'Glycolysis needs NAD⁺. When oxygen is short, NADH is reoxidised by reducing pyruvate to lactate, allowing glycolysis to keep producing its 2 ATP per glucose.', '{"0": "Converting pyruvate to lactate makes no ATP.", "1": "Lactic acid fermentation releases no CO₂.", "3": "Lactate is a by-product carried to the liver, not an energy store."}'),
  ('BIO-7050', 'Bioenergetics', 'Anaerobic respiration', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'In alcoholic fermentation by yeast, the molecule that is reduced by NADH to regenerate NAD⁺ is', '["pyruvate", "acetaldehyde", "ethanol", "carbon dioxide"]', 1, 'Pyruvate is first decarboxylated to acetaldehyde, releasing CO₂; acetaldehyde then accepts hydrogen from NADH and becomes ethanol.', '{"0": "In yeast, pyruvate is first decarboxylated; NADH reduces pyruvate in lactic acid fermentation.", "2": "Ethanol is the product of the reduction.", "3": "CO₂ is released, not reduced."}'),
  ('BIO-7051', 'Bioenergetics', 'ATP production', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'Which reaction makes ATP by substrate-level phosphorylation?', '["Flow of protons through ATP synthase", "Transfer of electrons from NADH to the first carrier of the chain", "Conversion of succinyl CoA to succinate in the Krebs cycle", "Reduction of oxygen to water"]', 2, 'In substrate-level phosphorylation a phosphate is passed directly from a substrate to ADP (or GDP); this happens in glycolysis and at the succinyl CoA step of the Krebs cycle.', '{"0": "ATP synthase makes ATP by oxidative phosphorylation (chemiosmosis).", "1": "Electron transfer releases energy to pump protons but does not itself form ATP.", "3": "Reducing oxygen ends the chain; it forms water, not ATP."}'),
  ('BIO-7052', 'Bioenergetics', 'Photosynthesis', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'A plant is supplied with carbon dioxide labelled with the heavy isotope ¹⁸O and ordinary water. The ¹⁸O will appear in', '["the oxygen released, not the carbohydrate", "the carbohydrate made in the Calvin cycle, not in the oxygen released", "both the oxygen released and the carbohydrate", "neither, because CO₂ oxygen is lost as water vapour"]', 1, 'All oxygen gas released in photosynthesis comes from the photolysis of water. The oxygen atoms of CO₂ are fixed in the Calvin cycle and end up in carbohydrate (and in water formed).', '{"0": "The released O₂ comes from water, so it would be labelled only if the water were labelled.", "2": "The released O₂ is not labelled because it comes from water.", "3": "The CO₂ oxygen is fixed into sugar."}'),
  ('BIO-7053', 'Bioenergetics', 'Calvin cycle', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'To make one molecule of glucose, the Calvin cycle uses', '["12 ATP and 18 NADPH", "18 ATP and 12 NADPH", "6 ATP and 6 NADPH", "3 ATP and 2 NADPH"]', 1, 'Fixing each CO₂ needs 3 ATP and 2 NADPH; a glucose molecule needs 6 CO₂, so 18 ATP and 12 NADPH.', '{"0": "The numbers of ATP and NADPH are reversed.", "2": "This is far too little for six turns of the cycle.", "3": "This is the cost of fixing one CO₂, not of one glucose."}'),
  ('BIO-7054', 'Bioenergetics', 'Limiting factors', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'At high light intensity, raising the light further does not increase the rate of photosynthesis, but raising the CO₂ concentration does. At this point the limiting factor was', '["light intensity", "chlorophyll concentration", "carbon dioxide concentration", "water supply"]', 2, 'By Blackman’s principle, the rate is controlled by the factor in shortest supply; since only extra CO₂ raised the rate, CO₂ was limiting.', '{"0": "More light had no effect, so light was not limiting.", "1": "Chlorophyll was not changed in the experiment.", "3": "Water was not changed in the experiment."}'),
  ('BIO-7055', 'Bioenergetics', 'Calvin cycle', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'A plant photosynthesising in bright light is suddenly placed in the dark. In the first moments, what happens to the levels of RuBP and phosphoglycerate (PGA)?', '["RuBP falls and PGA rises", "RuBP rises and PGA falls", "Both rise", "Both fall"]', 0, 'In the dark, ATP and NADPH run out, so PGA can no longer be reduced and RuBP cannot be regenerated; meanwhile RuBP keeps being used to fix CO₂ into PGA. So PGA builds up and RuBP falls.', '{"1": "This is what happens when CO₂, not light, is cut off.", "2": "RuBP is used up and not replaced.", "3": "PGA accumulates because it cannot be reduced."}'),
  ('BIO-7056', 'Bioenergetics', 'Cyclic photophosphorylation', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 6 Bioenergetics; PMDC MDCAT 2025 Biology 2; NUMS MDCAT 2026 Biology 2', 'A herbicide blocks photosystem II. In light, which process can still run in the treated chloroplasts?', '["Non-cyclic photophosphorylation, making ATP and NADPH", "Photolysis of water and release of oxygen", "Transfer of electrons from water to NADP⁺", "Cyclic photophosphorylation by photosystem I, making ATP only"]', 3, 'In cyclic flow, electrons excited in photosystem I return to it through the cytochrome complex, making ATP without needing photosystem II, water splitting or NADP⁺ reduction.', '{"0": "Non-cyclic flow needs photosystem II to pass electrons from water.", "1": "Water is split on the photosystem II side.", "2": "Electrons from water reach NADP⁺ only through photosystem II."}'),
  ('BIO-7057', 'Acellular life', 'HIV and AIDS', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'AZT, one of the first anti-HIV drugs, is a nucleotide analogue that stops the virus multiplying. It works by blocking', '["the attachment of gp120 to CD4 receptors", "the breakdown of the viral capsid", "the host cell’s ribosomes", "reverse transcriptase, so viral RNA cannot be copied into DNA"]', 3, 'HIV is a retrovirus: its reverse transcriptase builds DNA from the viral RNA. AZT is taken up into the growing DNA chain and ends it, so no proviral DNA is formed.', '{"0": "Blocking attachment is a different drug class (entry inhibitors).", "1": "Capsid breakdown is not the target of nucleotide analogues.", "2": "Blocking host ribosomes would kill the host cells too."}'),
  ('BIO-7058', 'Acellular life', 'HIV and AIDS', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'HIV mainly destroys helper T (CD4) lymphocytes, yet patients lose both antibody-mediated and cell-mediated immunity. This is because helper T cells', '["produce all the antibodies of the body", "are the only phagocytes in the blood", "make up the whole of the bone marrow", "are needed to activate both B cells and cytotoxic T cells"]', 3, 'Helper T cells release signals (cytokines) that switch on B cells to make antibodies and cytotoxic T cells to kill infected cells; without them both arms of specific immunity fail.', '{"0": "Antibodies are made by plasma cells derived from B cells.", "1": "The main phagocytes are neutrophils and macrophages.", "2": "Bone marrow contains many cell types; helper T cells mature in the thymus."}'),
  ('BIO-7059', 'Acellular life', 'Lysogenic cycle', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'A bacterium carries a prophage in its chromosome. It is exposed to ultraviolet light, which damages its DNA. The most likely result is that', '["the prophage becomes permanently fixed in the chromosome", "the bacterium becomes immune to all phages", "the prophage is cut out and enters the lytic cycle, bursting the cell", "the phage DNA is broken down by the host"]', 2, 'Stress such as UV light induces the prophage to leave the host chromosome; it then directs synthesis of new phages, which are released when the bacterium lyses.', '{"0": "Induction releases rather than fixes the prophage.", "1": "Lysogeny protects only against the same kind of phage, and induction ends it.", "3": "The phage genome is replicated, not destroyed."}'),
  ('BIO-7060', 'Acellular life', 'Structure of viruses', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'The envelope of the influenza virus is mainly', '["a lipid layer coded entirely by viral genes", "a peptidoglycan wall like that of bacteria", "a second protein capsid made by the virus", "part of the host cell’s plasma membrane, carrying virus-coded glycoproteins"]', 3, 'Enveloped viruses pick up a lipid bilayer when they bud out of the host cell; viral spike proteins (haemagglutinin and neuraminidase in influenza) are inserted into it.', '{"0": "Viruses do not code for lipid synthesis; the lipids come from the host.", "1": "Peptidoglycan is found only in bacterial walls.", "2": "The envelope is a lipid membrane outside the capsid, not a second capsid."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7061', 'Acellular life', 'Characteristics of viruses', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'Viruses cannot be grown on sterile nutrient agar like bacteria because they', '["are too small to settle on agar", "are killed by the glucose in the agar", "need a temperature above 60 °C to multiply", "lack ribosomes and enzymes for their own metabolism, so must use living host cells"]', 3, 'Viruses are obligate intracellular parasites; they carry only nucleic acid and a coat and must take over a living cell’s machinery to make new virus particles.', '{"0": "Size is not the reason; they cannot multiply outside cells.", "1": "Glucose does not kill viruses.", "2": "Viruses multiply at the host’s normal temperature."}'),
  ('BIO-7062', 'Acellular life', 'Classification of viruses', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'Which virus has a double-stranded DNA genome?', '["Herpes simplex virus", "Human immunodeficiency virus", "Influenza virus", "Poliovirus"]', 0, 'Herpes viruses are enveloped dsDNA viruses. HIV, influenza and poliovirus all have single-stranded RNA genomes.', '{"1": "HIV is a retrovirus with single-stranded RNA.", "2": "Influenza has a segmented single-stranded RNA genome.", "3": "Poliovirus has single-stranded RNA."}'),
  ('BIO-7063', 'Acellular life', 'Classification of viruses', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'A virus with an icosahedral head containing DNA attached to a helical tail with tail fibres has a complex shape. An example is', '["tobacco mosaic virus", "influenza virus", "poliovirus", "bacteriophage T4"]', 3, 'T-even bacteriophages combine a polyhedral head and a helical tail, so they are classed as complex viruses.', '{"0": "TMV is a rod-shaped helical virus.", "1": "Influenza is an enveloped virus without a tail.", "2": "Poliovirus is a small naked icosahedral virus."}'),
  ('BIO-7064', 'Acellular life', 'Prions and viroids', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 1; NUMS MDCAT 2026 Biology 1', 'An infectious agent causes a fatal brain disease. It is not affected by enzymes that digest nucleic acids but is inactivated by enzymes that digest protein. The agent is most likely', '["a viroid", "a DNA virus", "a prion", "a bacteriophage"]', 2, 'Prions are misfolded infectious proteins with no nucleic acid, so nucleases cannot harm them; they cause brain diseases such as Creutzfeldt–Jakob disease.', '{"0": "Viroids are naked RNA and would be destroyed by nucleases.", "1": "A DNA virus would be inactivated by nucleases acting on its genome.", "3": "Bacteriophages infect bacteria and contain nucleic acid."}'),
  ('BIO-7065', 'Human physiology', 'Cardiac cycle', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'At the start of ventricular systole there is a short phase when both the atrioventricular and the semilunar valves are closed. This phase is', '["atrial systole", "ventricular ejection", "isovolumetric ventricular contraction", "ventricular filling"]', 2, 'Ventricular pressure rises above atrial pressure, closing the AV valves, but is not yet above aortic and pulmonary pressure, so the semilunar valves stay shut; the volume of blood in the ventricles stays constant.', '{"0": "During atrial systole the AV valves are open.", "1": "During ejection the semilunar valves are open.", "3": "During filling the AV valves are open."}'),
  ('BIO-7066', 'Human physiology', 'Heart sounds', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'The first heart sound (“lub”) is caused by', '["closure of the semilunar valves at the end of ventricular systole", "closure of the atrioventricular valves at the start of ventricular systole", "opening of the atrioventricular valves", "contraction of the atria"]', 1, 'When the ventricles begin to contract, the tricuspid and bicuspid valves snap shut, producing the first, longer sound; the second sound “dub” is the closure of the semilunar valves.', '{"0": "Semilunar valve closure gives the second sound.", "2": "Valve opening is silent in a normal heart.", "3": "Atrial contraction does not produce the first sound."}'),
  ('BIO-7067', 'Human physiology', 'Cardiac output', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'A person’s heart rate is 75 beats per minute and the stroke volume is 80 cm³. The cardiac output is', '["155 cm³ per minute", "6.0 dm³ per minute", "0.94 dm³ per minute", "60 dm³ per minute"]', 1, 'Cardiac output = heart rate × stroke volume = 75 × 80 = 6000 cm³ = 6.0 dm³ per minute.', '{"0": "This adds the two numbers instead of multiplying.", "2": "This divides stroke volume by heart rate.", "3": "This is ten times too large."}'),
  ('BIO-7068', 'Human physiology', 'Blood vessels', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Which blood vessel normally carries blood with the highest oxygen content?', '["Pulmonary artery", "Inferior vena cava", "Pulmonary vein", "Coronary sinus"]', 2, 'The pulmonary veins return freshly oxygenated blood from the lungs to the left atrium; the pulmonary artery carries deoxygenated blood from the right ventricle.', '{"0": "The pulmonary artery carries deoxygenated blood to the lungs.", "1": "The vena cava returns deoxygenated blood from the body.", "3": "The coronary sinus drains deoxygenated blood from the heart wall."}'),
  ('BIO-7069', 'Human physiology', 'Capillary exchange', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'People with very low plasma protein levels, as in severe malnutrition, develop oedema (tissue swelling). The main reason is that', '["blood pressure at the arterial end becomes zero", "lymph vessels secrete extra fluid", "red blood cells leak into the tissues", "lower osmotic pressure of plasma means less tissue fluid returns at the venous end of capillaries"]', 3, 'Plasma proteins create the osmotic pull that draws fluid back into capillaries at the venous end. With fewer proteins, more fluid stays in the tissues than the lymphatics can drain.', '{"0": "Arterial blood pressure is not abolished by low protein.", "1": "Lymph vessels drain fluid; they do not secrete it.", "2": "Red cells stay in the vessels; oedema is fluid."}'),
  ('BIO-7070', 'Human physiology', 'Blood vessels', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Blood flows most slowly through the capillaries because', '["each capillary has a thick muscular wall", "capillaries are farthest from the heart", "their total cross-sectional area is far larger than that of the arteries", "capillary blood is more viscous than arterial blood"]', 2, 'Although each capillary is narrow, there are billions of them, so their combined cross-section is huge; the same volume of blood per minute moving through a larger total area moves more slowly, allowing time for exchange.', '{"0": "Capillary walls are one cell thick.", "1": "Distance from the heart alone does not decide speed; veins are farther still but blood speeds up again in them.", "3": "Blood viscosity is similar throughout."}'),
  ('BIO-7071', 'Human physiology', 'Conduction of the heartbeat', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'The impulse from the sinoatrial node is delayed by about 0.1 s at the atrioventricular node. This delay is important because it', '["allows the semilunar valves to open first", "gives the SA node time to recharge", "stops the ventricles from ever contracting together", "lets the atria finish contracting and fill the ventricles before the ventricles contract"]', 3, 'The AV node delay ensures atrial systole is complete, so the ventricles are full before the impulse spreads down the bundle of His and Purkinje fibres.', '{"0": "Semilunar valves open later, during ventricular ejection.", "1": "The SA node fires on its own rhythm; the AV delay is not for it.", "2": "Both ventricles contract together after the delay."}'),
  ('BIO-7072', 'Human physiology', 'Lymphatic system', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 11 Human circulatory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'In filariasis, worms block lymph vessels of the legs, which swell greatly. The swelling occurs because', '["arteries in the legs burst", "too many red blood cells are made in the legs", "plasma protein concentration rises sharply", "tissue fluid that leaves the capillaries cannot drain back into the blood"]', 3, 'Lymph vessels collect excess tissue fluid and return it to the veins. When they are blocked, fluid accumulates in the tissues (lymphoedema).', '{"0": "Arterial rupture causes bleeding, not chronic swelling.", "1": "Red blood cells are made in red bone marrow, not the leg tissues.", "2": "A rise in plasma protein would pull fluid back into the blood."}'),
  ('BIO-7073', 'Human physiology', 'Surfactant', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 10 Human respiratory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Babies born very prematurely often have great difficulty breathing because', '["their haemoglobin cannot carry oxygen", "their diaphragm has not formed", "their trachea lacks cartilage rings", "their lungs have not yet made enough surfactant, so the alveoli tend to collapse"]', 3, 'Surfactant lowers the surface tension of the fluid lining the alveoli; without enough of it the alveoli collapse after each breath and are hard to reinflate (respiratory distress syndrome).', '{"0": "Fetal haemoglobin carries oxygen well.", "1": "The diaphragm is formed long before birth.", "2": "Tracheal cartilage is present in premature babies."}'),
  ('BIO-7074', 'Human physiology', 'Effects of smoking', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 10 Human respiratory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'In emphysema, caused mainly by smoking, gas exchange becomes poor chiefly because', '["the bronchi are blocked by thick mucus only", "the alveoli make too much surfactant", "the walls between alveoli break down, greatly reducing surface area", "the diaphragm becomes paralysed"]', 2, 'Enzymes released during chronic inflammation destroy alveolar walls; many small alveoli merge into fewer large air spaces, so the area for diffusion falls and the lungs lose elasticity.', '{"0": "Excess mucus is the main problem in chronic bronchitis.", "1": "Surfactant production is not increased in emphysema.", "3": "The diaphragm is not paralysed."}'),
  ('BIO-7075', 'Human physiology', 'Mechanism of breathing', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 10 Human respiratory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'During quiet (normal) expiration,', '["the internal intercostal muscles contract strongly", "the diaphragm contracts and flattens", "the diaphragm relaxes and domes upward, and elastic recoil of the lungs pushes air out", "the external intercostal muscles contract"]', 2, 'Quiet expiration is largely passive: the inspiratory muscles relax and the stretched lungs and chest wall recoil, raising pressure in the lungs above atmospheric pressure.', '{"0": "Internal intercostals are used in forced expiration only.", "1": "Diaphragm contraction is part of inspiration.", "3": "External intercostals contract during inspiration."}'),
  ('BIO-7076', 'Human physiology', 'Control of breathing', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 10 Human respiratory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'During exercise the rate and depth of breathing increase mainly because chemoreceptors detect', '["a rise in blood oxygen", "a rise in carbon dioxide (and H⁺) in the blood", "a fall in blood pressure", "a fall in body temperature"]', 1, 'Working muscles release more CO₂, which forms carbonic acid and lowers blood pH; chemoreceptors in the medulla and in the aortic and carotid bodies respond and the breathing centre speeds up ventilation.', '{"0": "Blood oxygen does not rise during exercise.", "2": "Blood pressure generally rises during exercise.", "3": "Body temperature rises, not falls, during exercise."}'),
  ('BIO-7077', 'Human physiology', 'Oxygen transport', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 10 Human respiratory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'In actively respiring muscle, haemoglobin gives up more of its oxygen than in resting tissue mainly because', '["muscle haemoglobin contains more iron", "the temperature of active muscle is lower", "higher CO₂ and lower pH reduce haemoglobin’s affinity for oxygen", "carbon monoxide is produced by muscles"]', 2, 'This is the Bohr effect: acid and CO₂ from respiration change haemoglobin’s shape so it releases O₂ more readily where it is most needed.', '{"0": "Haemoglobin is in red blood cells, and its iron content is the same everywhere.", "1": "Active muscle is warmer, which also helps unloading.", "3": "Muscles do not produce carbon monoxide."}'),
  ('BIO-7078', 'Human physiology', 'Carbon dioxide transport', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 10 Human respiratory system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Most of the carbon dioxide carried from the tissues to the lungs travels as', '["carbaminohaemoglobin", "hydrogen carbonate (bicarbonate) ions in the plasma", "CO₂ dissolved in plasma", "carbonic acid inside red blood cells"]', 1, 'In red cells, carbonic anhydrase rapidly converts CO₂ and water to carbonic acid, which dissociates; the HCO₃⁻ ions move out into the plasma, carrying most of the CO₂.', '{"0": "Carbaminohaemoglobin carries a smaller share.", "2": "Only a small fraction travels dissolved.", "3": "Carbonic acid dissociates at once; it is not the carrier form."}'),
  ('BIO-7079', 'Human physiology', 'Bile', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 9 Human digestive system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'A gallstone completely blocks the common bile duct. The patient’s faeces are most likely to be', '["pale and fatty, because fats are poorly emulsified and absorbed", "watery and full of undigested starch", "dark and full of undigested protein", "normal, because bile has no digestive role"]', 0, 'Bile salts emulsify fat for lipase, and bile pigments colour the faeces. With no bile reaching the gut, fat passes out undigested and the stools lose their brown colour.', '{"1": "Starch digestion depends on amylase, not bile.", "2": "Bile pigments darken faeces; without them stools are pale.", "3": "Bile is essential for fat digestion even though it has no enzymes."}'),
  ('BIO-7080', 'Human physiology', 'Pancreatic juice', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 9 Human digestive system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'The hormone secretin is released from the duodenum when acidic chyme arrives. It stimulates', '["the pancreas to secrete juice rich in hydrogen carbonate", "the stomach to secrete more hydrochloric acid", "the gall bladder to contract strongly", "the salivary glands to secrete amylase"]', 0, 'Secretin causes the pancreas to release alkaline, bicarbonate-rich juice that neutralises stomach acid and gives pancreatic enzymes their optimum pH.', '{"1": "Secretin reduces, rather than increases, acid secretion.", "2": "Gall bladder contraction is mainly caused by cholecystokinin (CCK).", "3": "Salivary secretion is under nervous control."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7081', 'Human physiology', 'Pancreatic enzymes', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 9 Human digestive system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Trypsinogen released into the duodenum is first converted to active trypsin by', '["pepsin from the stomach", "enterokinase from the intestinal lining", "hydrochloric acid", "bile salts"]', 1, 'Enterokinase (enteropeptidase) made by the duodenal wall activates the first trypsin; trypsin then activates more trypsinogen and other pancreatic zymogens.', '{"0": "Pepsin is inactive at duodenal pH and does not activate trypsinogen.", "2": "HCl activates pepsinogen in the stomach, not trypsinogen.", "3": "Bile salts emulsify fats; they do not activate enzymes."}'),
  ('BIO-7082', 'Human physiology', 'Absorption', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 9 Human digestive system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'After digestion, most absorbed fat first enters', '["the hepatic portal vein as free fatty acids", "the lacteals (lymph vessels) of the villi as chylomicrons", "the blood capillaries of the villi as glycerol only", "the stomach wall"]', 1, 'Fatty acids and monoglycerides are rebuilt into triglycerides in the epithelial cells, coated with protein as chylomicrons and passed into the lacteals, reaching the blood later via the thoracic duct.', '{"0": "Glucose and amino acids, not most fats, go to the hepatic portal vein.", "2": "Most fat is carried as chylomicrons in lymph, not as glycerol in blood.", "3": "Little absorption occurs in the stomach."}'),
  ('BIO-7083', 'Human physiology', 'Stomach', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'After most of the stomach is surgically removed, a patient develops anaemia unless given vitamin B₁₂ injections. This is because the stomach normally provides', '["pepsin, which makes iron soluble", "mucus, which stores vitamin B₁₂", "intrinsic factor from parietal (oxyntic) cells, needed to absorb vitamin B₁₂", "gastrin, which makes red blood cells"]', 2, 'Parietal cells secrete both HCl and intrinsic factor; intrinsic factor binds vitamin B₁₂ so it can be absorbed in the ileum. Without it, B₁₂ deficiency causes pernicious anaemia.', '{"0": "Pepsin digests proteins; it is not needed for B₁₂ uptake.", "1": "Mucus protects the stomach lining; it does not store B₁₂.", "3": "Gastrin stimulates acid secretion, not red cell production."}'),
  ('BIO-7084', 'Human physiology', 'Liver', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 9 Human digestive system; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Which of the following is NOT a function of the liver?', '["Secreting lipase into the duodenum", "Forming urea from excess amino acids", "Storing glucose as glycogen", "Making the plasma protein fibrinogen"]', 0, 'Lipase reaching the duodenum comes from the pancreas. The liver deaminates amino acids and makes urea, stores glycogen, makes plasma proteins and produces bile, which has no enzymes.', '{"1": "The liver makes urea through the ornithine cycle.", "2": "The liver stores glycogen under the influence of insulin.", "3": "Fibrinogen and most plasma proteins are made in the liver."}'),
  ('BIO-7085', 'Human physiology', 'Muscle contraction', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human skeletal and muscular systems; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'When a skeletal muscle fibre contracts, which part of the sarcomere stays the same length?', '["A band", "I band", "H zone", "The whole sarcomere"]', 0, 'The A band is the length of the thick myosin filaments, which do not shorten; thin filaments slide over them, so the I band and H zone narrow and the sarcomere shortens.', '{"1": "The I band shortens as thin filaments slide inward.", "2": "The H zone narrows or disappears.", "3": "The sarcomere shortens during contraction."}'),
  ('BIO-7086', 'Human physiology', 'Muscle contraction', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human skeletal and muscular systems; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'In skeletal muscle, the role of calcium ions released from the sarcoplasmic reticulum is to', '["bind directly to myosin heads and split ATP", "break cross-bridges between actin and myosin", "bind troponin, moving tropomyosin to expose binding sites on actin", "bind acetylcholine receptors on the sarcolemma"]', 2, 'At rest, tropomyosin covers the myosin-binding sites on actin. Ca²⁺ binds troponin, which shifts tropomyosin aside so myosin heads can attach and form cross-bridges.', '{"0": "Myosin heads split ATP themselves; Ca²⁺ does not bind them for this.", "1": "Cross-bridges are broken by ATP binding to myosin.", "3": "Acetylcholine, not Ca²⁺, binds the receptors on the sarcolemma."}'),
  ('BIO-7087', 'Human physiology', 'Muscle contraction', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human skeletal and muscular systems; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Muscles become stiff a few hours after death (rigor mortis) because', '["calcium ions are pumped back into the sarcoplasmic reticulum", "actin filaments are digested", "acetylcholine keeps stimulating the muscle", "without ATP, myosin heads cannot detach from actin"]', 3, 'ATP binding is needed to release each myosin head from actin. After death ATP runs out, so cross-bridges stay locked.', '{"0": "Calcium leaks out after death; pumping it back needs ATP.", "1": "Digestion of filaments later ends rigor; it does not cause it.", "2": "Nerve stimulation stops at death."}'),
  ('BIO-7088', 'Human physiology', 'Arthritis', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 12 Human skeletal and muscular systems; PMDC MDCAT 2025 Biology 9, 11, 13, 14; NUMS MDCAT 2026 Biology 9, 12', 'Rheumatoid arthritis differs from osteoarthritis in that rheumatoid arthritis', '["is caused mainly by wear and tear of articular cartilage with age", "affects only one large weight-bearing joint", "is caused by uric acid crystals", "is an autoimmune inflammation of the synovial membrane"]', 3, 'In rheumatoid arthritis the immune system attacks the synovial membrane, often of many small joints on both sides; osteoarthritis is degeneration of articular cartilage with age and use.', '{"0": "Wear of cartilage with age describes osteoarthritis.", "1": "Rheumatoid arthritis typically affects many joints symmetrically.", "2": "Uric acid crystals cause gout."}'),
  ('BIO-7089', 'Homeostasis', 'Selective reabsorption', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'In untreated diabetes mellitus, glucose appears in the urine because', '["the glomerulus becomes permeable to glucose only in diabetes", "the loop of Henle actively secretes glucose", "the absence of ADH prevents glucose reabsorption", "the filtered glucose exceeds the capacity of the carriers that reabsorb it in the proximal tubule"]', 3, 'Glucose is always filtered, and normally all of it is reabsorbed by carrier proteins in the proximal convoluted tubule. When blood glucose is very high, the filtered load saturates these carriers and the excess stays in the urine.', '{"0": "Glucose is freely filtered in healthy people too.", "1": "The loop of Henle does not secrete glucose.", "2": "ADH controls water reabsorption, not glucose."}'),
  ('BIO-7090', 'Homeostasis', 'Glomerular filtration', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'Protein is found in a person’s urine on repeated tests. The part of the nephron most likely to be damaged is the', '["glomerulus and its filtration membrane", "loop of Henle", "collecting duct", "distal convoluted tubule"]', 0, 'Plasma proteins are too large to pass the healthy glomerular filter, so protein in urine points to damage of the glomerular capillaries or basement membrane.', '{"1": "The loop of Henle handles salt and water, not protein filtration.", "2": "The collecting duct adjusts water; it does not let proteins in.", "3": "The distal tubule adjusts ions; protein entry happens at the filter."}'),
  ('BIO-7091', 'Homeostasis', 'Glomerular filtration', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'Blood pressure in the glomerulus is higher than in most capillaries, which drives ultrafiltration. This is mainly because', '["the glomerulus is supplied directly by the aorta", "the efferent arteriole is narrower than the afferent arteriole", "the glomerular capillaries have thick muscular walls", "the renal vein is wider than the renal artery"]', 1, 'Blood enters through a wide afferent arteriole but leaves through a narrower efferent arteriole, so pressure builds up in the glomerular capillaries and forces fluid into Bowman’s capsule.', '{"0": "The glomerulus is supplied by the renal artery via afferent arterioles.", "2": "Capillary walls are thin; they have no muscle.", "3": "Vein width does not create the glomerular pressure."}'),
  ('BIO-7092', 'Homeostasis', 'Loop of Henle', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'The thick ascending limb of the loop of Henle', '["is freely permeable to water but not to salts", "secretes urea into the filtrate", "actively pumps Na⁺ and Cl⁻ out and is impermeable to water", "reabsorbs all the glucose"]', 2, 'Salt pumped out of the water-tight ascending limb makes the medulla hypertonic, so water can later leave the descending limb and collecting duct by osmosis (the counter-current multiplier).', '{"0": "This describes the descending limb.", "1": "Urea is not secreted here.", "3": "Glucose is reabsorbed in the proximal tubule."}'),
  ('BIO-7093', 'Homeostasis', 'ADH', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'A person’s pituitary does not release antidiuretic hormone (ADH). The person will produce', '["small volumes of concentrated urine", "urine containing large amounts of glucose", "large volumes of dilute urine containing no glucose", "urine containing plasma proteins"]', 2, 'Without ADH the collecting ducts stay impermeable to water, so little water is reabsorbed (diabetes insipidus). The urine is copious and dilute but, unlike diabetes mellitus, has no glucose.', '{"0": "Concentrated urine needs ADH acting on the collecting ducts.", "1": "Glucose in urine is a sign of diabetes mellitus.", "3": "Plasma proteins in urine point to glomerular damage."}'),
  ('BIO-7094', 'Homeostasis', 'Aldosterone', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'Which hormone increases the reabsorption of Na⁺ and the secretion of K⁺ in the distal convoluted tubule and collecting duct?', '["ADH", "Atrial natriuretic peptide", "Aldosterone", "Calcitonin"]', 2, 'Aldosterone from the adrenal cortex, released via the renin–angiotensin system when blood volume or sodium is low, makes the distal nephron take back Na⁺ in exchange for K⁺.', '{"0": "ADH controls water permeability.", "1": "Atrial natriuretic peptide increases Na⁺ loss.", "3": "Calcitonin lowers blood calcium."}'),
  ('BIO-7095', 'Homeostasis', 'Tubular secretion', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'The antibiotic penicillin is removed from the blood by the kidneys much faster than glomerular filtration alone could achieve. This is because penicillin is', '["reabsorbed in the proximal convoluted tubule", "filtered only, at a higher pressure than other solutes", "broken down in the loop of Henle", "actively secreted from the peritubular capillaries into the tubule"]', 3, 'Tubular secretion moves substances such as penicillin, H⁺, K⁺ and some drugs from the peritubular capillary blood into the tubule, adding to the amount filtered at the glomerulus.', '{"0": "Reabsorption would slow, not speed up, its removal.", "1": "All small solutes are filtered at the same glomerular pressure.", "2": "The loop of Henle concentrates urine; it does not destroy drugs."}'),
  ('BIO-7096', 'Homeostasis', 'Kidney stones', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'Lithotripsy treats a kidney stone by', '["dissolving the stone with strong acid", "removing the whole kidney", "increasing the calcium content of the diet", "using shock waves to break the stone into small pieces that pass out in urine"]', 3, 'Lithotripsy focuses shock waves from outside the body on the stone, shattering it into fragments small enough to be flushed out with urine.', '{"0": "Acid is not used to dissolve stones inside the body.", "1": "Lithotripsy avoids removing the kidney.", "2": "More dietary calcium does not remove a stone."}'),
  ('BIO-7097', 'Homeostasis', 'Kidney failure', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 14 Human urinary system; PMDC MDCAT 2025 Biology 15', 'In haemodialysis, the dialysis fluid contains glucose at the same concentration as normal blood plasma but no urea. The glucose is included so that', '["glucose diffuses into the blood to feed the patient", "urea is pushed out by the glucose", "glucose is not lost from the patient’s blood by diffusion", "the dialysis membrane is kept open"]', 2, 'Substances move down their own concentration gradients across the partially permeable membrane. Matching glucose stops it diffusing out, while urea, absent from the fluid, diffuses out of the blood.', '{"0": "Equal concentrations give no net movement of glucose.", "1": "Each substance diffuses down its own gradient; glucose does not drive urea.", "3": "Glucose does not keep the membrane open."}'),
  ('BIO-7098', 'Homeostasis', 'Excretion', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 13 Homeostasis; PMDC MDCAT 2025 Biology 15', 'Birds and insects excrete most of their nitrogenous waste as uric acid. The main advantage of this is that uric acid', '["is the most toxic waste, so it is removed quickly", "requires no energy to produce", "is nearly insoluble and non-toxic, so it can be excreted with very little water", "dissolves easily in large volumes of water"]', 2, 'Uric acid can be stored safely and passed as a paste, saving water; this suits animals that lay shelled eggs or live in dry habitats. Ammonia is highly toxic and needs much water to flush out.', '{"0": "Ammonia, not uric acid, is the most toxic nitrogenous waste.", "1": "Making uric acid costs more energy than making ammonia.", "3": "Its low solubility is the point; it is not dissolved in much water."}'),
  ('BIO-7099', 'Homeostasis', 'Excretion', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 13 Homeostasis; PMDC MDCAT 2025 Biology 15', 'Patients with severe liver failure develop dangerously high levels of ammonia in the blood because', '["the kidneys secrete more ammonia into the blood", "muscles stop using amino acids", "the intestine stops absorbing ammonia", "the liver can no longer convert ammonia into urea by the ornithine cycle"]', 3, 'Ammonia from deamination of amino acids (and from gut bacteria) is turned into much less toxic urea in the liver; when the liver fails this conversion stops and ammonia builds up.', '{"0": "Kidneys excrete nitrogenous wastes; they do not add ammonia to the blood.", "1": "Amino acid breakdown continues and keeps producing ammonia.", "2": "Gut ammonia is still absorbed; it is the liver that fails to detoxify it."}'),
  ('BIO-7100', 'Homeostasis', 'Thermoregulation', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 13 Homeostasis; PMDC MDCAT 2025 Biology 15', 'On a cold day, the arterioles supplying the skin capillaries constrict. This', '["increases sweating to keep the skin warm", "increases heat loss by radiation", "raises the metabolic rate of skin cells", "reduces blood flow near the skin surface, reducing heat loss"]', 3, 'Vasoconstriction diverts blood away from the surface capillaries, so less heat reaches the skin to be lost to the cold air.', '{"0": "Sweating cools the body and is reduced in the cold.", "1": "Less blood at the surface means less radiation of heat.", "2": "Vasoconstriction itself does not raise skin cell metabolism."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7101', 'Homeostasis', 'Thermoregulation', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 15', 'At the start of a fever, a person shivers and feels cold although the body temperature is already rising. This is because', '["the skin temperature receptors have stopped working", "pyrogens have reset the hypothalamic set point higher, so normal temperature is sensed as too cold", "the hypothalamus has been destroyed", "sweating has started"]', 1, 'Pyrogens released during infection raise the thermostat setting of the hypothalamus; until body temperature reaches the new set point, heat-gaining responses such as shivering and vasoconstriction are switched on.', '{"0": "Skin receptors still work; the set point has changed.", "2": "A destroyed hypothalamus could not drive shivering.", "3": "Sweating happens when the fever breaks, not at its start."}'),
  ('BIO-7102', 'Homeostasis', 'Osmoregulation', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 15', 'A freshwater fish lives in water that is hypotonic to its body fluids. To osmoregulate it', '["drinks large amounts of water and excretes salts through its gills", "produces small volumes of concentrated urine", "produces large volumes of dilute urine and actively absorbs salts through its gills", "stops all water from entering through its gills"]', 2, 'Water keeps entering by osmosis, so the fish removes it as copious dilute urine and replaces lost ions by active uptake at the gills. Marine bony fish do the opposite.', '{"0": "Drinking and excreting salt at the gills is how marine bony fish cope.", "1": "Concentrated urine would be needed in a hypertonic environment.", "3": "The gills cannot be made fully waterproof because they exchange gases."}'),
  ('BIO-7103', 'Coordination and control', 'Resting membrane potential', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'A neuron is treated with ouabain, which blocks the Na⁺/K⁺ pump. Over time,', '["the resting potential instantly becomes +40 mV", "the neuron fires continuous action potentials forever", "the membrane becomes impermeable to ions", "the resting potential gradually runs down as Na⁺ and K⁺ gradients are lost"]', 3, 'The pump moves 3 Na⁺ out and 2 K⁺ in using ATP, maintaining the ion gradients on which the resting potential depends. Without it, leakage slowly erases the gradients.', '{"0": "The potential falls gradually, not instantly to the action potential peak.", "1": "Without gradients, action potentials eventually cannot occur.", "2": "Leak channels remain; the membrane does not become impermeable."}'),
  ('BIO-7104', 'Coordination and control', 'Nerve impulse', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'Local anaesthetics such as lidocaine block voltage-gated Na⁺ channels in sensory nerves. As a result,', '["the resting potential is reversed", "action potentials cannot be generated or conducted, so pain is not felt", "neurotransmitter release becomes continuous", "K⁺ can no longer leave during repolarisation"]', 1, 'Depolarisation during an action potential depends on the rapid inflow of Na⁺ through voltage-gated channels. Blocking them stops impulses travelling to the brain.', '{"0": "The resting potential is set mainly by K⁺ leak and the pump.", "2": "Without impulses arriving, transmitter release falls.", "3": "K⁺ channels are not the target."}'),
  ('BIO-7105', 'Coordination and control', 'Myelination', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'In multiple sclerosis, myelin sheaths in the central nervous system are destroyed. Nerve conduction slows mainly because', '["the axons become thicker", "impulses can no longer jump from one node of Ranvier to the next", "synapses release more neurotransmitter", "sodium channels are removed from the nodes"]', 1, 'Myelin insulates the axon so that depolarisation occurs only at the nodes, allowing saltatory conduction. Without myelin, the impulse must travel continuously and slowly, or fails.', '{"0": "Demyelination does not thicken axons.", "2": "Transmitter release is not the cause of slowed conduction.", "3": "The problem is loss of insulation, not removal of nodal channels."}'),
  ('BIO-7106', 'Coordination and control', 'Nerve impulse', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'An impulse travelling along an axon does not turn back towards the cell body because', '["synapses only release transmitter from axon terminals", "the membrane just behind the impulse is in its refractory period", "myelin blocks backward movement", "the sodium–potassium pump pushes the impulse forward"]', 1, 'After an action potential, Na⁺ channels are inactivated for a short time, so the region just passed cannot fire again; the impulse can only spread forward into resting membrane.', '{"0": "This explains one-way transmission across a synapse, not along an axon.", "2": "Myelin speeds conduction but does not set its direction.", "3": "The pump restores gradients; it does not drive the impulse."}'),
  ('BIO-7107', 'Coordination and control', 'Chemical synapse', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'If Ca²⁺ ions are removed from the fluid around a chemical synapse, transmission stops because', '["Ca²⁺ is the neurotransmitter itself", "Ca²⁺ entry is needed to make vesicles release neurotransmitter", "Ca²⁺ is needed to generate the action potential in the axon", "Ca²⁺ breaks down acetylcholine in the cleft"]', 1, 'When an impulse reaches the terminal, voltage-gated Ca²⁺ channels open; Ca²⁺ flows in and triggers vesicles to fuse with the membrane and release transmitter by exocytosis.', '{"0": "Neurotransmitters are substances such as acetylcholine.", "2": "The axon action potential depends on Na⁺ and K⁺.", "3": "Acetylcholine is broken down by acetylcholinesterase."}'),
  ('BIO-7108', 'Coordination and control', 'Electrical synapse', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'Electrical synapses differ from chemical synapses in that', '["they use acetylcholine as transmitter", "ions pass directly between cells through gap junctions with almost no delay", "they transmit in one direction only", "they have a wide synaptic cleft"]', 1, 'At electrical synapses the membranes are joined by protein channels (gap junctions), so current flows straight through, very quickly and often in both directions.', '{"0": "Electrical synapses use no chemical transmitter.", "2": "They can usually transmit in both directions.", "3": "The cells are very close; the cleft is wide in chemical synapses."}'),
  ('BIO-7109', 'Coordination and control', 'Nerve impulse', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'A stronger stimulus applied to a sensory neuron is signalled to the brain by', '["larger action potentials", "faster action potentials in the same axon", "longer action potentials", "a higher frequency of action potentials of the same size"]', 3, 'Action potentials obey the all-or-none law, so their size is fixed; intensity is coded by how often they are fired (and how many neurons fire).', '{"0": "Action potential size is constant.", "1": "Conduction speed depends on the axon, not stimulus strength.", "2": "Each action potential lasts about the same time."}'),
  ('BIO-7110', 'Coordination and control', 'Reflex arc', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'In the knee-jerk reflex, how many synapses lie between the sensory neuron and the motor neuron in the spinal cord?', '["Two", "Three", "None", "One"]', 3, 'The knee-jerk is a monosynaptic stretch reflex: the sensory neuron synapses directly with the motor neuron, with no relay neuron.', '{"0": "Two synapses would need one relay neuron, as in withdrawal reflexes.", "1": "Three synapses would need two relay neurons.", "2": "A reflex arc always has at least one synapse in the CNS."}'),
  ('BIO-7111', 'Coordination and control', 'Spinal cord', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'If the ventral root of a spinal nerve is cut, the area it supplies will', '["lose sensation but keep movement", "be paralysed but still have sensation", "lose both sensation and movement", "be unaffected"]', 1, 'The ventral root carries motor fibres out of the cord, while the dorsal root carries sensory fibres in. Cutting the ventral root stops commands to muscles but leaves sensation intact.', '{"0": "Loss of sensation follows cutting the dorsal root.", "2": "Both would be lost only if the whole spinal nerve were cut.", "3": "Motor supply is lost, so the area is affected."}'),
  ('BIO-7112', 'Coordination and control', 'Brain', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'After a head injury, a person walks with a staggering gait and poor balance but has normal muscle strength and sensation. The part of the brain most likely damaged is the', '["medulla oblongata", "cerebellum", "hypothalamus", "thalamus"]', 1, 'The cerebellum coordinates muscle activity, posture and balance; damage causes clumsy, unsteady movement while strength is normal.', '{"0": "Medulla damage affects breathing, heart rate and blood pressure.", "2": "The hypothalamus controls temperature, thirst and the pituitary.", "3": "The thalamus relays sensory information; damage affects sensation."}'),
  ('BIO-7113', 'Coordination and control', 'Brain', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'Damage to which part of the brain is most immediately life-threatening?', '["Cerebellum", "Occipital lobe", "Medulla oblongata", "Corpus callosum"]', 2, 'The medulla contains the vital centres that control breathing, heart rate and blood pressure.', '{"0": "Cerebellar damage affects coordination, not vital functions.", "1": "Occipital damage affects vision.", "3": "Corpus callosum damage affects communication between hemispheres."}'),
  ('BIO-7114', 'Coordination and control', 'Spinal cord', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'A spinal cord injury in the neck (cervical) region is generally more serious than one in the lumbar region because it', '["can paralyse both arms and legs and may affect breathing", "affects only the legs", "affects only the bladder", "has no effect on sensation"]', 0, 'Nerves to the arms and to the diaphragm leave from the cervical cord; an injury there cuts off everything below, including the legs, while a lumbar injury affects mainly the legs.', '{"1": "Leg-only paralysis is typical of lower injuries.", "2": "Bladder control is lost in both, but cervical injury does far more.", "3": "Sensation below the injury is lost too."}'),
  ('BIO-7115', 'Coordination and control', 'Receptors', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 15 Human nervous system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'All sensory receptors act as transducers. This means that they', '["convert the energy of a stimulus into electrical nerve impulses", "respond to every type of stimulus equally", "carry impulses from the brain to effectors", "release hormones into the blood"]', 0, 'Whether the stimulus is light, sound, pressure, heat or chemicals, a receptor changes it into a generator potential and then action potentials in a sensory neuron.', '{"1": "Each receptor is specialised for one kind of stimulus.", "2": "Motor neurons carry impulses to effectors.", "3": "Hormones are released by endocrine glands."}'),
  ('BIO-7116', 'Coordination and control', 'Feedback mechanism', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 16 Human endocrine system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'In iodine deficiency, the thyroid gland enlarges (goitre). The best explanation is that', '["low thyroxine removes negative feedback, so more TSH is released and overstimulates the thyroid", "excess thyroxine stimulates the thyroid to grow", "iodine itself directly causes thyroid cells to divide", "TSH secretion stops completely"]', 0, 'Without iodine the thyroid cannot make enough thyroxine. Low thyroxine no longer inhibits the hypothalamus and anterior pituitary, so TSH rises and drives the gland to grow.', '{"1": "Thyroxine is low, not high, in iodine deficiency.", "2": "It is the lack of iodine, through TSH, that causes growth.", "3": "TSH rises; it does not stop."}'),
  ('BIO-7117', 'Coordination and control', 'Feedback mechanism', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 16 Human endocrine system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'Which is an example of positive feedback?', '["Oxytocin release during childbirth, which strengthens uterine contractions that release more oxytocin", "Insulin release when blood glucose rises", "Inhibition of TSH by thyroxine", "ADH release when blood becomes concentrated"]', 0, 'In positive feedback the response increases the stimulus; contractions stretch the cervix, more oxytocin is released and contractions intensify until birth.', '{"1": "Insulin lowers glucose and so reduces its own stimulus.", "2": "Thyroxine lowering TSH is negative feedback.", "3": "ADH conserves water and dilutes the blood, removing the stimulus."}'),
  ('BIO-7118', 'Coordination and control', 'Hormones', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 16 Human endocrine system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'In untreated type 1 diabetes, blood glucose is very high, yet muscle and fat cells behave as if they are starved of glucose. This is because', '["glucose is too large to leave the capillaries", "the liver stores all the glucose as glycogen", "insulin is needed for these cells to take up glucose from the blood", "glucagon secretion stops completely"]', 2, 'Without insulin from the β cells, muscle and adipose cells do not insert glucose carriers into their membranes, so glucose stays in the blood while the cells break down fat and protein for energy.', '{"0": "Glucose leaves capillaries freely; the block is at the cell membrane.", "1": "Without insulin the liver releases rather than stores glucose.", "3": "Glucagon is high, not absent, which raises blood glucose further."}'),
  ('BIO-7119', 'Coordination and control', 'Hormones', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 16 Human endocrine system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'Steroid hormones differ from peptide hormones in that steroid hormones', '["bind receptors on the cell surface and act through cAMP", "are made on rough endoplasmic reticulum", "cross the plasma membrane and bind receptors inside the cell, changing gene expression", "act only on nerve cells"]', 2, 'Lipid-soluble steroids pass through the membrane; the hormone–receptor complex binds DNA and switches genes on or off. Peptide hormones cannot cross the membrane and use surface receptors and second messengers.', '{"0": "Surface receptors and cAMP are typical of peptide hormones.", "1": "Steroids are made on smooth ER.", "3": "Steroid hormones act on many tissues."}'),
  ('BIO-7120', 'Coordination and control', 'Hormones', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 16 Human endocrine system; PMDC MDCAT 2025 Biology 5; NUMS MDCAT 2026 Biology 5', 'An adult develops enlarged hands, feet and jaw over several years. The most likely cause is', '["excess growth hormone secreted before puberty", "deficient thyroxine in childhood", "excess growth hormone secreted after the growth plates have closed", "deficient growth hormone in adulthood"]', 2, 'In adults, excess growth hormone cannot lengthen the long bones, so it thickens bones of the hands, feet and face (acromegaly). Before puberty the same excess causes gigantism.', '{"0": "Excess before puberty causes gigantism, with tall stature.", "1": "Childhood thyroxine deficiency causes cretinism.", "3": "Deficiency would not enlarge bones."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7121', 'Reproduction', 'Menstrual cycle', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'The surge of LH that triggers ovulation is brought about by', '["positive feedback from the high level of oestrogen secreted by the maturing follicle", "a fall in progesterone from the corpus luteum", "inhibition of FSH by inhibin", "hCG released by the embryo"]', 0, 'Low oestrogen early in the cycle inhibits LH, but when oestrogen from the Graafian follicle stays high for a while it switches to stimulating the hypothalamus and pituitary, causing the mid-cycle LH (and FSH) surge.', '{"1": "Falling progesterone at the end of the cycle leads to menstruation, not ovulation.", "2": "Inhibin lowers FSH; it does not cause an LH surge.", "3": "hCG is produced only after implantation."}'),
  ('BIO-7122', 'Reproduction', 'Menstrual cycle', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'Menstruation begins at the end of a cycle in which no fertilisation occurs because', '["FSH secretion suddenly rises to a peak", "the LH surge destroys the endometrium", "the corpus luteum degenerates, so progesterone and oestrogen levels fall", "oestrogen from a new follicle breaks down the endometrium"]', 2, 'Progesterone from the corpus luteum maintains the thick endometrium. Without hCG from an embryo, the corpus luteum breaks down about 12–14 days after ovulation, hormone levels drop and the lining is shed.', '{"0": "FSH starts rising after progesterone falls; it does not cause shedding.", "1": "The LH surge causes ovulation mid-cycle.", "3": "Oestrogen from a new follicle rebuilds the endometrium after menstruation."}'),
  ('BIO-7123', 'Reproduction', 'Menstrual cycle', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'Home pregnancy tests work by detecting a hormone in the urine that is made by the developing embryo. This hormone, which keeps the corpus luteum alive, is', '["human chorionic gonadotrophin (hCG)", "luteinising hormone (LH)", "follicle-stimulating hormone (FSH)", "oxytocin"]', 0, 'Soon after implantation, the trophoblast (later the placenta) secretes hCG, which maintains the corpus luteum so progesterone stays high; hCG passes into the urine.', '{"1": "LH comes from the mother’s pituitary and falls after ovulation.", "2": "FSH comes from the pituitary and is kept low in pregnancy.", "3": "Oxytocin acts at birth and in milk ejection."}'),
  ('BIO-7124', 'Reproduction', 'Hormonal control', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'The combined contraceptive pill, containing an oestrogen and a progestogen, prevents pregnancy mainly by', '["killing sperm in the vagina", "keeping FSH and LH low by negative feedback, so no follicle matures and ovulation does not occur", "making the corpus luteum secrete more hCG", "blocking the oviducts permanently"]', 1, 'Steady levels of the synthetic hormones inhibit the hypothalamus and anterior pituitary, so FSH and LH stay low and there is no mid-cycle LH surge.', '{"0": "The pill is not a spermicide.", "2": "hCG is made by an embryo, not the corpus luteum.", "3": "The pill’s effect is hormonal and reversible."}'),
  ('BIO-7125', 'Reproduction', 'Male reproductive system', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'A drug selectively destroys the interstitial (Leydig) cells of the testes. The first hormone level to fall would be', '["testosterone", "FSH", "LH", "inhibin"]', 0, 'LH acts on the interstitial cells, which make testosterone. Without these cells, testosterone falls; LH would then rise because negative feedback is removed.', '{"1": "FSH acts on Sertoli cells; it is made by the pituitary.", "2": "LH would rise, not fall, after loss of feedback.", "3": "Inhibin comes from Sertoli cells, which are not destroyed."}'),
  ('BIO-7126', 'Reproduction', 'Gametogenesis', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', '100 primary spermatocytes and 100 primary oocytes complete meiosis. How many functional gametes are formed?', '["400 sperms and 100 ova", "400 sperms and 400 ova", "100 sperms and 100 ova", "200 sperms and 100 ova"]', 0, 'Each primary spermatocyte gives four spermatids that become sperms, but each primary oocyte gives only one ovum, the other products being polar bodies.', '{"1": "Most of the oocyte’s divisions produce polar bodies, not ova.", "2": "Each spermatocyte gives four sperms, not one.", "3": "Each spermatocyte gives four, not two, sperms."}'),
  ('BIO-7127', 'Reproduction', 'Male reproductive system', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'A man whose testes have remained in the abdomen (undescended testes) is usually infertile because', '["the testes cannot make testosterone in the abdomen", "sperm cannot pass through the abdominal wall", "FSH cannot reach the abdominal cavity", "spermatogenesis needs a temperature a few degrees below core body temperature"]', 3, 'The scrotum keeps the testes about 2–3 °C cooler than the body core; at body temperature sperm production fails, although testosterone production can continue.', '{"0": "Testosterone is still made by interstitial cells.", "1": "The ducts do not pass through the abdominal wall in that way; sperm are not made.", "2": "Hormones reach all tissues through the blood."}'),
  ('BIO-7128', 'Reproduction', 'Male reproductive system', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'Which is the correct path of sperms from their place of formation to the outside?', '["Seminiferous tubules → epididymis → vas deferens → ejaculatory duct → urethra", "Epididymis → seminiferous tubules → vas deferens → urethra → ejaculatory duct", "Seminiferous tubules → vas deferens → epididymis → urethra", "Seminiferous tubules → epididymis → urethra → vas deferens"]', 0, 'Sperms form in the seminiferous tubules, mature and are stored in the epididymis, travel in the vas deferens, join the seminal vesicle duct at the ejaculatory duct and leave through the urethra.', '{"1": "Sperms are made in the seminiferous tubules before reaching the epididymis.", "2": "The epididymis comes before the vas deferens.", "3": "The vas deferens comes before the urethra."}'),
  ('BIO-7129', 'Reproduction', 'Male reproductive system', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'After a vasectomy, in which both vasa deferentia are cut and tied, a man', '["ejaculates semen without sperms but has normal testosterone levels", "stops producing testosterone", "cannot produce semen at all", "stops producing sperms in the testes"]', 0, 'Cutting the vas deferens stops sperms from reaching the urethra; the seminal fluid from the glands is still ejaculated, and the interstitial cells continue to release testosterone into the blood.', '{"1": "Testosterone enters the blood, not the vas deferens.", "2": "The seminal vesicles and prostate still add fluid.", "3": "Spermatogenesis continues; the sperms are reabsorbed."}'),
  ('BIO-7130', 'Reproduction', 'Sexually transmitted diseases', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'A patient has a painless, firm ulcer on the genitals that heals by itself; months later a skin rash appears. The most likely disease and its cause are', '["gonorrhoea, caused by Neisseria gonorrhoeae", "syphilis, caused by the bacterium Treponema pallidum", "genital herpes, caused by herpes simplex virus", "AIDS, caused by HIV"]', 1, 'A painless chancre at the site of infection is the primary stage of syphilis; the secondary stage brings a skin rash as the spirochaete spreads.', '{"0": "Gonorrhoea mainly causes painful urination and discharge.", "2": "Herpes causes painful blisters, not a painless chancre.", "3": "HIV infection does not begin with a genital chancre."}'),
  ('BIO-7131', 'Reproduction', 'Sexually transmitted diseases', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'Which sexually transmitted disease is caused by a virus that stays latent in nerve ganglia and causes repeated outbreaks of painful blisters?', '["Syphilis", "Genital herpes", "Gonorrhoea", "Chlamydia infection"]', 1, 'Herpes simplex virus (usually HSV-2) hides in sensory nerve ganglia between attacks and reactivates, causing recurrent blisters; antibiotics do not cure it.', '{"0": "Syphilis is caused by a bacterium.", "2": "Gonorrhoea is caused by a bacterium.", "3": "Chlamydia is a bacterium."}'),
  ('BIO-7132', 'Reproduction', 'Menstrual cycle', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 17 Human reproductive systems; PMDC MDCAT 2025 Biology 8; NUMS MDCAT 2026 Biology 11', 'The endometrium is thickest, most glandular and best prepared for implantation during the', '["luteal (secretory) phase, under the influence of progesterone", "follicular (proliferative) phase, under the influence of FSH alone", "menstrual phase", "first day after the LH surge only"]', 0, 'Oestrogen rebuilds the lining in the follicular phase, but in the luteal phase progesterone from the corpus luteum makes it thick, well supplied with blood and glandular, ready for an embryo about a week after ovulation.', '{"1": "The lining is being rebuilt in this phase, and FSH acts on follicles, not the endometrium.", "2": "The lining is being shed.", "3": "The lining keeps developing for about a week after ovulation."}'),
  ('BIO-7133', 'Immunity', 'Types of immunity', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'A person with a deep, dirty wound is given an injection of anti-tetanus serum containing ready-made antibodies. This gives', '["artificially acquired active immunity, which lasts for years", "naturally acquired active immunity", "naturally acquired passive immunity", "artificially acquired passive immunity, which acts at once but is short-lived"]', 3, 'The antibodies were made by another organism and injected, so the body’s own lymphocytes are not activated and no memory cells form; protection is immediate but fades as the antibodies are broken down.', '{"0": "Active immunity requires the person’s own immune response, as after a vaccine.", "1": "Natural active immunity follows an actual infection.", "2": "Natural passive immunity comes from the mother via the placenta or milk."}'),
  ('BIO-7134', 'Immunity', 'Secondary response', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'A booster dose of vaccine gives a faster and larger antibody response than the first dose because', '["the booster contains more antigen than the first dose", "antibodies from the first dose are still at their peak level", "memory cells formed after the first dose are quickly activated", "the booster contains ready-made antibodies"]', 2, 'Memory B and T cells from the primary response persist; on re-exposure they multiply rapidly into plasma cells, giving a quicker, stronger and longer-lasting secondary response.', '{"0": "The response depends on memory, not antigen dose.", "1": "Antibodies from the first dose have usually fallen by the time of a booster.", "3": "Vaccines contain antigens, not antibodies."}'),
  ('BIO-7135', 'Immunity', 'Cell-mediated immunity', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'Viruses that are already inside body cells are mainly dealt with by', '["antibodies, which enter the infected cells", "cytotoxic T cells, which kill the infected cells", "plasma cells, which engulf the infected cells", "helper T cells, which make antibodies"]', 1, 'Antibodies act on free virus outside cells. Infected cells display viral antigens on their surface and are destroyed by cytotoxic (killer) T cells, for example with perforin.', '{"0": "Antibodies cannot cross the plasma membrane into cells.", "2": "Plasma cells secrete antibodies; they do not engulf cells.", "3": "Helper T cells activate other cells; they do not make antibodies."}'),
  ('BIO-7136', 'Immunity', 'Antibodies', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'The ability of an antibody to bind one specific antigen is determined by', '["the variable regions at the tips of its heavy and light chains", "the constant region of its heavy chains", "the disulphide bonds holding the chains together", "the hinge region"]', 0, 'Each antibody arm ends in variable regions of one heavy and one light chain whose amino acid sequence forms a binding site complementary to one antigen.', '{"1": "The constant region decides the antibody class and its effects.", "2": "Disulphide bonds hold the shape together but do not give specificity.", "3": "The hinge gives flexibility, not specificity."}'),
  ('BIO-7137', 'Immunity', 'Antibodies', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'The first class of antibody produced in a primary immune response is a large pentamer. It is', '["IgG", "IgA", "IgE", "IgM"]', 3, 'IgM, made of five Y-shaped units, appears first; later in the response and in secondary responses IgG predominates.', '{"0": "IgG predominates later and in secondary responses.", "1": "IgA is found mainly in secretions such as tears and milk.", "2": "IgE is involved in allergies and defence against worms."}'),
  ('BIO-7138', 'Immunity', 'Clonal selection', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'According to the clonal selection theory, when an antigen enters the body,', '["it selects the few lymphocytes that already carry matching receptors, which then multiply into a clone", "lymphocytes change their receptors to fit the antigen", "all lymphocytes divide equally", "antibodies are made by moulding around the antigen"]', 0, 'Each lymphocyte is committed to one specificity before it meets antigen; the antigen binds only matching cells, which divide to produce effector and memory cells.', '{"1": "Receptor specificity is fixed before antigen contact.", "2": "Only the selected lymphocytes multiply.", "3": "The old template idea was rejected; antibody shape is coded by genes."}'),
  ('BIO-7139', 'Immunity', 'Lymphocytes', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'A child is born without a thymus. The child will most clearly lack', '["mature T lymphocytes", "B lymphocytes", "neutrophils", "red blood cells"]', 0, 'T cells are made in the bone marrow but mature in the thymus; without it, cell-mediated immunity is severely weak (and B-cell responses also suffer without T-cell help).', '{"1": "B cells mature in the bone marrow.", "2": "Neutrophils form in the bone marrow.", "3": "Red cells form in the bone marrow."}'),
  ('BIO-7140', 'Immunity', 'Antibody production', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'Plasma cells contain an unusually large amount of rough endoplasmic reticulum because they', '["engulf and digest many bacteria", "secrete large quantities of antibody protein", "store lipids for energy", "divide very rapidly by mitosis"]', 1, 'Antibodies are glycoproteins secreted from the cell, so plasma cells are packed with rough ER and Golgi to make and export them.', '{"0": "Phagocytosis is done by neutrophils and macrophages.", "2": "Lipid storage is not their role.", "3": "Plasma cells are end cells that rarely divide."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7141', 'Immunity', 'Rh factor', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'An Rh-negative mother is given anti-D antibodies soon after delivering her first Rh-positive baby. This protects her next Rh-positive baby because the injected antibodies', '["destroy fetal Rh-positive cells in her blood before her own immune system can make memory cells", "stimulate her to make anti-D antibodies", "change her blood group to Rh-positive", "cross into the next baby to protect its red cells"]', 0, 'Fetal cells entering her blood at birth would normally sensitise her. Anti-D removes them quickly, so she never mounts her own anti-D response; in a later pregnancy no harmful IgG attacks the fetus.', '{"1": "The aim is to stop her own production of anti-D.", "2": "A blood group cannot be changed by antibodies.", "3": "The injected antibodies are gone by the next pregnancy."}'),
  ('BIO-7142', 'Immunity', 'Transplant rejection', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 21 Immunity; PMDC MDCAT 2025 Biology 12; NUMS MDCAT 2026 Biology 9.8', 'A transplanted kidney from an unrelated donor is rejected mainly by', '["red blood cells attacking the kidney", "T lymphocytes recognising the donor cells’ foreign surface (MHC) proteins", "antibodies made against the kidney’s glucose", "platelets blocking the renal artery"]', 1, 'Donor cells carry tissue-type (MHC) proteins that differ from the recipient’s; T cells recognise them as foreign and attack, so immunosuppressant drugs are given.', '{"0": "Red blood cells play no part in graft rejection.", "2": "Rejection is directed against foreign proteins, not glucose.", "3": "Platelets are not the main cause of rejection."}'),
  ('BIO-7143', 'Inheritance', 'Gene linkage', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A test cross AaBb × aabb produces offspring in the ratio 42% AaBb, 42% aabb, 8% Aabb and 8% aaBb. What is the distance between genes A and B?', '["8 map units", "42 map units", "84 map units", "16 map units"]', 3, 'The large classes are parental and the small ones recombinant. Recombination frequency = 8% + 8% = 16%, and 1% recombination = 1 map unit.', '{"0": "This counts only one recombinant class.", "1": "42% is one parental class.", "2": "84% is the total of parental types."}'),
  ('BIO-7144', 'Inheritance', 'Independent assortment', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'If genes A, B and C assort independently, what fraction of the offspring of AaBbCc × AaBbCc will be aabbcc?', '["1/8", "1/16", "1/64", "1/32"]', 2, 'For each gene, Aa × Aa gives aa with probability 1/4. For three independent genes: 1/4 × 1/4 × 1/4 = 1/64.', '{"0": "1/8 multiplies three halves instead of three quarters.", "1": "1/16 is the answer for two genes.", "3": "1/32 mixes a half and two quarters."}'),
  ('BIO-7145', 'Inheritance', 'Dihybrid cross', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'In the cross AaBb × AaBb (unlinked genes), what fraction of offspring is heterozygous for both genes?', '["9/16", "1/16", "1/4", "1/2"]', 2, 'P(Aa) = 1/2 and P(Bb) = 1/2, so P(AaBb) = 1/2 × 1/2 = 1/4 (4 of the 16 boxes).', '{"0": "9/16 is the fraction showing both dominant traits.", "1": "1/16 is the fraction of any one homozygous genotype, such as AABB.", "3": "1/2 is the chance of being heterozygous for one gene."}'),
  ('BIO-7146', 'Inheritance', 'Haemophilia', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A woman who carries haemophilia marries a man with normal blood clotting. What is the probability that their next child will be a son with haemophilia?', '["1/2", "1/8", "1/4", "0"]', 2, 'Mother XᴴXʰ × father XᴴY gives XᴴXᴴ, XᴴXʰ, XᴴY and XʰY in equal proportions; one in four children is an affected son (half of all sons).', '{"0": "1/2 is the chance among the sons only, not among all children.", "1": "1/8 halves the correct answer again.", "3": "Sons receive their X from the mother, so they can be affected."}'),
  ('BIO-7147', 'Inheritance', 'Haemophilia', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A man with haemophilia marries a woman who is not a carrier. Which statement about their children is correct?', '["Half the sons will have haemophilia", "All daughters will be carriers, and no son will have haemophilia", "All children will have haemophilia", "All sons will be carriers"]', 1, 'The father passes his Xʰ to every daughter (who also receive a normal X from the mother) and his Y to every son, who get a normal X from the mother.', '{"0": "Sons get their X chromosome from their normal mother.", "2": "Daughters get a normal X from the mother, so they are carriers, not affected.", "3": "Males cannot be carriers; they have only one X."}'),
  ('BIO-7148', 'Inheritance', 'Sex linkage in humans', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A colour-blind woman marries a man with normal colour vision. Which outcome is expected?', '["All sons colour-blind and all daughters carriers", "All daughters colour-blind and all sons normal", "Half the sons colour-blind and half the daughters carriers", "All children normal"]', 0, 'The mother is XᶜXᶜ, so every child gets Xᶜ from her. Sons (XᶜY) are colour-blind; daughters also get the father’s normal X and are carriers.', '{"1": "Daughters get a normal X from the father, so they are not colour-blind.", "2": "Every son gets Xᶜ from the mother.", "3": "Every son receives the recessive allele and shows it."}'),
  ('BIO-7149', 'Inheritance', 'Multiple alleles', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A couple with blood groups A and B have a child with blood group O. What is the probability that their next child will have blood group AB?', '["1/2", "1/4", "0", "3/4"]', 1, 'An O child (ii) means both parents carry i: the parents are Iᴬi and Iᴮi. Their children are Iᴬ Iᴮ, Iᴬi, Iᴮi and ii in equal numbers, so the chance of AB is 1/4.', '{"0": "1/2 would require one parent to be homozygous.", "2": "AB is possible because each parent has one of the two dominant alleles.", "3": "3/4 is the chance of not being AB."}'),
  ('BIO-7150', 'Inheritance', 'Incomplete dominance', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'Two pink-flowered four o’clock plants (Mirabilis jalapa) are crossed. The expected offspring are', '["3 red : 1 white", "1 red : 2 pink : 1 white", "all pink", "3 pink : 1 white"]', 1, 'Red (RR) and white (WW) are incompletely dominant, so the heterozygote is pink. RW × RW gives RR : RW : WW in a 1 : 2 : 1 ratio, and each genotype has its own colour.', '{"0": "3 : 1 is the ratio for complete dominance.", "2": "Only crossing red with white gives all pink.", "3": "Pink plants cannot give a 3 : 1 ratio with white."}'),
  ('BIO-7151', 'Inheritance', 'Epistasis', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'In a dihybrid cross, the F₂ shows a phenotypic ratio of 9 : 3 : 4. This indicates', '["recessive epistasis", "dominant epistasis", "complementary gene action", "incomplete dominance at one locus"]', 0, 'In recessive epistasis, being homozygous recessive at one gene (for example cc for coat colour) masks the other gene, so two classes (3 + 1) merge into one, giving 9 : 3 : 4.', '{"1": "Dominant epistasis gives 12 : 3 : 1.", "2": "Complementary genes give 9 : 7.", "3": "Incomplete dominance changes 3 : 1 into 1 : 2 : 1, not 9 : 3 : 3 : 1 into 9 : 3 : 4."}'),
  ('BIO-7152', 'Inheritance', 'Polygenic inheritance', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A trait is controlled by three genes with equal, additive effects (each dominant allele adds the same amount). How many phenotypic classes appear among the offspring of AaBbCc × AaBbCc?', '["6", "7", "8", "27"]', 1, 'Offspring can carry 0, 1, 2, 3, 4, 5 or 6 dominant (adding) alleles, giving 7 phenotypic classes; this many classes approaches continuous variation, as in human skin colour.', '{"0": "Six forgets the class with no adding alleles.", "2": "Eight is the number of gamete types.", "3": "27 is the number of different genotypes."}'),
  ('BIO-7153', 'Inheritance', 'Sex linkage in Drosophila', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'Morgan crossed a red-eyed female Drosophila (pure-breeding) with a white-eyed male. In the F₂ obtained by crossing the F₁ flies, white eyes appeared', '["only in females", "in a quarter of the females and a quarter of the males", "in all the males", "only in males, about half of them"]', 3, 'P: XᴿXᴿ × XʳY → F₁ XᴿXʳ and XᴿY (all red). F₂: females XᴿXᴿ and XᴿXʳ (all red); males XᴿY and XʳY (half white). This showed the gene is on the X chromosome.', '{"0": "Every F₂ female gets the father’s Xᴿ, so none is white-eyed.", "1": "White eyes do not appear in females in this F₂.", "2": "Half of the males receive the mother’s Xᴿ and are red-eyed."}'),
  ('BIO-7154', 'Inheritance', 'Crossing over', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'Crossing over, which produces new combinations of linked genes, takes place', '["between sister chromatids during mitosis", "between non-homologous chromosomes during anaphase II", "between non-sister chromatids of homologous chromosomes during prophase I of meiosis", "during DNA replication in interphase"]', 2, 'Homologous chromosomes pair (synapsis) in prophase I and non-sister chromatids exchange segments at chiasmata, recombining alleles of linked genes.', '{"0": "Exchange between identical sister chromatids would not create new combinations.", "1": "Crossing over is between homologues, in prophase I.", "3": "It happens after replication, during meiosis."}'),
  ('BIO-7155', 'Inheritance', 'Independent assortment', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'Ignoring crossing over, how many genetically different gametes can an organism with 2n = 8 produce?', '["8", "4", "256", "16"]', 3, 'There are 4 homologous pairs, and each pair lines up independently at metaphase I, so the number of combinations is 2⁴ = 16.', '{"0": "8 confuses 2n with the number of combinations.", "1": "4 is the number of homologous pairs.", "2": "256 is 2⁸, using the diploid number."}'),
  ('BIO-7156', 'Inheritance', 'Test cross', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A tall pea plant is crossed with a dwarf plant, and the offspring are about half tall and half dwarf. This shows that the tall parent was', '["homozygous dominant (TT)", "homozygous recessive (tt)", "polyploid", "heterozygous (Tt)"]', 3, 'A test cross with tt reveals the unknown genotype: TT × tt gives all tall, while Tt × tt gives 1 tall : 1 dwarf.', '{"0": "TT × tt would give only tall offspring.", "1": "A tt plant would be dwarf, not tall.", "2": "Polyploidy is not shown by a 1 : 1 ratio."}'),
  ('BIO-7157', 'Inheritance', 'Probability in genetics', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'Two parents are both carriers of albinism, an autosomal recessive trait. What is the probability that all three of their children will have normal pigmentation?', '["3/4", "9/16", "27/64", "1/64"]', 2, 'Each child independently has a 3/4 chance of being normal (AA or Aa). For three children: 3/4 × 3/4 × 3/4 = 27/64.', '{"0": "3/4 is the chance for one child only.", "1": "9/16 is the chance for two children.", "3": "1/64 is the chance that all three are albino."}'),
  ('BIO-7158', 'Inheritance', 'Pedigree analysis', 'hard', 'Pedigree analysis; AKU MBBS entrance test practice paper (Biology); PMDC MDCAT 2025 Biology 10.5–10.7', 'In a pedigree, two unaffected parents have an affected daughter. The trait must be inherited as', '["an X-linked recessive trait", "an autosomal dominant trait", "an autosomal recessive trait", "an X-linked dominant trait"]', 2, 'Unaffected parents with an affected child means the trait is recessive and both parents are carriers. An affected daughter of an unaffected father rules out X-linked recessive, because she would have to receive an affected X from him.', '{"0": "An X-linked recessive daughter needs an affected father.", "1": "A dominant trait would show in at least one parent.", "3": "A dominant trait would show in at least one parent."}'),
  ('BIO-7159', 'Inheritance', 'Pedigree analysis', 'hard', 'Pedigree analysis; AKU MBBS entrance test practice paper (Biology); PMDC MDCAT 2025 Biology 10.5–10.6', 'In a family, every daughter of an affected man shows a rare trait, but none of his sons do, and his wife is unaffected. The trait is most likely', '["X-linked dominant", "X-linked recessive", "autosomal recessive", "Y-linked"]', 0, 'A father passes his X to every daughter and his Y to every son. If all daughters (but no sons) are affected, the trait is on the X and shows with one copy, so it is dominant.', '{"1": "X-linked recessive daughters of a normal mother would be carriers, not affected.", "2": "An autosomal trait would show no sex difference of this kind.", "3": "A Y-linked trait would affect all the sons and no daughters."}'),
  ('BIO-7160', 'Inheritance', 'Multiple alleles', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 18 Inheritance; PMDC MDCAT 2025 Biology 10; NUMS MDCAT 2026 Biology 13', 'A man with blood group AB marries a woman with blood group O. Their children can have blood group', '["AB or O only", "A, B, AB or O", "A or B only", "AB only"]', 2, 'The father (IᴬIᴮ) gives either Iᴬ or Iᴮ and the mother (ii) always gives i, so children are Iᴬi (group A) or Iᴮi (group B), never AB or O.', '{"0": "AB needs both Iᴬ and Iᴮ, but the mother gives only i; O needs i from the father, who has none.", "1": "Only two genotypes are possible from this cross.", "3": "Every child receives i from the mother, so none is AB."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7161', 'Chromosomes and DNA', 'DNA replication', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'In the Meselson–Stahl experiment, bacteria grown for many generations in ¹⁵N were moved to ¹⁴N medium. After two rounds of replication, the DNA would be', '["all hybrid", "one quarter heavy and three quarters light", "all light", "half hybrid (¹⁵N/¹⁴N) and half light (¹⁴N/¹⁴N)"]', 3, 'Replication is semi-conservative. After one round every molecule has one heavy and one light strand. In the second round each hybrid gives one hybrid and one light molecule, so half are hybrid and half light.', '{"0": "All hybrid is the result after one round.", "1": "No fully heavy DNA remains after the first round.", "2": "Hybrid molecules persist in every later generation."}'),
  ('BIO-7162', 'Chromosomes and DNA', 'DNA as hereditary material', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'In the Hershey–Chase experiment, phages with ³⁵S-labelled protein coats were allowed to infect bacteria, and the mixture was then blended and centrifuged. Most of the radioactivity was found', '["in the supernatant with the empty phage coats", "inside the bacterial cells in the pellet", "in the new phages released later", "equally in the pellet and the supernatant"]', 0, 'Only phage DNA enters the bacterium; the protein coat stays outside and is shaken off by the blender, so ³⁵S remains in the liquid. With ³²P-labelled DNA, radioactivity went into the cells, showing DNA is the genetic material.', '{"1": "³²P (DNA), not ³⁵S (protein), was found in the bacterial pellet.", "2": "Protein from the parent phage is not passed to new phages.", "3": "The protein coats separate clearly from the cells."}'),
  ('BIO-7163', 'Chromosomes and DNA', 'DNA as hereditary material', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'Avery, MacLeod and McCarty found that an extract of heat-killed S-strain pneumococci could transform R-strain bacteria. Which treatment of the extract destroyed its transforming ability?', '["Protease", "Ribonuclease (RNase)", "Removal of the polysaccharide capsule", "Deoxyribonuclease (DNase)"]', 3, 'Only the enzyme that digests DNA stopped transformation; protease and RNase had no effect, showing the transforming principle was DNA.', '{"0": "Protease left transformation intact, so protein was not the factor.", "1": "RNase left transformation intact, so RNA was not the factor.", "2": "The capsule is the trait being transferred, not the transforming agent."}'),
  ('BIO-7164', 'Chromosomes and DNA', 'DNA replication', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'A mutant cell makes no functional DNA ligase. During DNA replication this would mainly affect', '["unwinding of the double helix", "making RNA primers", "adding nucleotides to the leading strand", "joining of Okazaki fragments on the lagging strand"]', 3, 'DNA ligase seals the gaps between Okazaki fragments after their primers are replaced; without it the lagging strand stays in pieces.', '{"0": "Unwinding is done by helicase.", "1": "Primers are made by primase.", "2": "DNA polymerase extends the leading strand continuously."}'),
  ('BIO-7165', 'Chromosomes and DNA', 'DNA replication', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'The lagging strand is made in short pieces during replication because', '["the lagging template strand is shorter", "helicase works only on one strand", "DNA polymerase can add nucleotides only to the 3′ end, but the two template strands are antiparallel", "RNA primers are needed only on the lagging strand"]', 2, 'Polymerase synthesises 5′ → 3′. On one template this runs towards the replication fork (leading strand); on the other it runs away from it, so synthesis restarts repeatedly as the fork opens.', '{"0": "Both strands are the same length.", "1": "Helicase unwinds both strands at the fork.", "3": "The leading strand also needs a primer, though only one."}'),
  ('BIO-7166', 'Chromosomes and DNA', 'Transcription', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'A DNA template strand has the base sequence 3′–TAC CGA TTC–5′. The mRNA transcribed from it is', '["5′–ATG GCT AAG–3′", "5′–UAC CGA UUC–3′", "3′–AUG GCU AAG–5′", "5′–AUG GCU AAG–3′"]', 3, 'RNA is complementary and antiparallel to the template: T→A, A→U, C→G, G→C, with the mRNA running 5′ to 3′ opposite the template’s 3′ to 5′.', '{"0": "RNA contains uracil, not thymine.", "1": "This copies the template instead of pairing with it.", "2": "The bases are right but the strand direction is reversed."}'),
  ('BIO-7167', 'Chromosomes and DNA', 'Translation', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'An mRNA codon is 5′–GCU–3′. The anticodon of the tRNA that pairs with it is', '["5′–CGA–3′", "3′–CGT–5′", "3′–GCU–5′", "3′–CGA–5′"]', 3, 'Codon and anticodon pair complementarily and antiparallel: G–C, C–G, U–A, so the anticodon read 3′ to 5′ is CGA.', '{"0": "The bases are right, but pairing must be antiparallel.", "1": "tRNA contains U, not T.", "2": "This repeats the codon instead of pairing with it."}'),
  ('BIO-7168', 'Chromosomes and DNA', 'Genetic code', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'A substitution in the third base of a codon often has no effect on the protein because', '["the third base is never read by ribosomes", "third-base changes always produce stop codons", "the genetic code is degenerate, so several codons code for the same amino acid", "tRNA ignores all bases of the codon"]', 2, 'Most amino acids have more than one codon, and these usually differ only at the third position, so a change there frequently gives the same amino acid (a silent mutation).', '{"0": "All three bases are read.", "1": "Most third-base changes are silent, not stop codons.", "3": "The anticodon pairs with the codon."}'),
  ('BIO-7169', 'Chromosomes and DNA', 'Mutations', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'Which mutation within a gene is most likely to destroy the function of its protein completely?', '["Deletion of a single base near the start of the coding sequence", "Substitution of the third base of a codon", "Deletion of three adjacent bases near the end of the gene", "Substitution that replaces one amino acid with a very similar one"]', 0, 'A single-base deletion shifts the reading frame, so every codon after it is changed and a stop codon usually appears early (frameshift).', '{"1": "Third-base changes are often silent.", "2": "A three-base deletion removes one amino acid without a frameshift, and near the end.", "3": "A conservative substitution may leave the protein working."}'),
  ('BIO-7170', 'Chromosomes and DNA', 'Mutations', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'In sickle cell anaemia, the sixth codon of the β-globin gene changes from GAG to GTG. This is', '["a frameshift mutation", "a deletion of one codon", "a chromosomal translocation", "a point (substitution) mutation that replaces glutamic acid with valine"]', 3, 'One base is substituted (A→T), so one amino acid changes: glutamic acid becomes valine, making haemoglobin S polymerise at low oxygen.', '{"0": "No base is added or lost, so the frame is unchanged.", "1": "The codon is altered, not removed.", "2": "Only one base pair is involved."}'),
  ('BIO-7171', 'Chromosomes and DNA', 'Chromosome structure', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'Histone proteins bind tightly to DNA in nucleosomes mainly because histones', '["are rich in negatively charged amino acids", "form covalent bonds with the bases", "are made of the same nucleotides as DNA", "are rich in positively charged amino acids that attract negatively charged phosphate groups"]', 3, 'Histones contain many lysine and arginine residues; their positive charges attract the negative phosphates of the DNA backbone, letting DNA wrap around histone octamers.', '{"0": "Negative charges would repel the DNA backbone.", "1": "The binding is mostly ionic, not covalent bonding to bases.", "2": "Histones are proteins, not nucleotides."}'),
  ('BIO-7172', 'Chromosomes and DNA', 'Nondisjunction', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'Non-disjunction of the X and Y chromosomes during meiosis I in a man can produce sperms carrying', '["two X chromosomes or two Y chromosomes only", "one X or one Y only", "three sex chromosomes", "both X and Y, or no sex chromosome"]', 3, 'If X and Y fail to separate in meiosis I, one secondary spermatocyte gets both and the other gets neither, giving XY and O sperms; these can lead to XXY (Klinefelter) or XO (Turner) zygotes.', '{"0": "XX or YY sperms arise from non-disjunction in meiosis II.", "1": "Single X or Y sperms are normal.", "2": "Three sex chromosomes cannot be produced by one meiosis I error."}'),
  ('BIO-7173', 'Chromosomes and DNA', 'Gene regulation', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'E. coli growing on lactose (with no glucose) produces the enzymes of the lac operon because', '["lactose binds the operator and switches on transcription", "the repressor gene is deleted when lactose is present", "lactose (allolactose) binds the repressor so it cannot attach to the operator", "lactose activates the ribosomes directly"]', 2, 'The repressor normally sits on the operator and blocks RNA polymerase. The inducer changes the repressor’s shape so it falls off, allowing transcription of the structural genes.', '{"0": "The inducer binds the repressor, not the operator.", "1": "The repressor gene is still present and expressed.", "3": "The control is at transcription, not at the ribosome."}'),
  ('BIO-7174', 'Chromosomes and DNA', 'Transcription', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 19 Chromosome and DNA; PMDC MDCAT 2025 Biology 3.9-3.10, 4.4', 'Unlike DNA polymerase, RNA polymerase', '["can start a new chain without a primer", "synthesises chains in the 3′ → 5′ direction", "uses deoxyribonucleotides", "needs DNA ligase to join its products"]', 0, 'RNA polymerase begins transcription at a promoter on its own, while DNA polymerase can only extend an existing primer.', '{"1": "Both polymerases synthesise 5′ → 3′.", "2": "RNA polymerase uses ribonucleotides.", "3": "Transcripts are made continuously; ligase is not needed."}'),
  ('BIO-7175', 'Biotechnology', 'Restriction enzymes', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'To insert a human gene into a plasmid, both are usually cut with the same restriction enzyme because', '["one enzyme is cheaper than two", "restriction enzymes also act as ligases", "this gives matching sticky ends that can base-pair before ligase seals them", "only one enzyme can cut circular DNA"]', 2, 'A restriction enzyme cuts at a specific palindromic site, leaving identical single-stranded overhangs on both DNAs; these complementary ends pair, and DNA ligase joins the backbones.', '{"0": "Cost is not the reason.", "1": "Restriction enzymes cut; ligase joins.", "3": "Many enzymes can cut circular DNA."}'),
  ('BIO-7176', 'Biotechnology', 'Restriction enzymes', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 16', 'Assuming the four bases occur at random and in equal amounts, a restriction enzyme that recognises a particular 6-base-pair sequence will cut DNA on average once every', '["24 base pairs", "4096 base pairs", "256 base pairs", "1296 base pairs"]', 1, 'Each position has a 1/4 chance of matching, so a given 6-base sequence occurs with probability (1/4)⁶ = 1/4096.', '{"0": "This multiplies 6 by 4.", "2": "4⁴ = 256 is for a 4-base site.", "3": "6⁴ inverts the base and exponent."}'),
  ('BIO-7177', 'Biotechnology', 'PCR', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'Starting from a single double-stranded DNA molecule, how many copies of the target DNA are present (ideally) after 10 cycles of PCR?', '["1024", "20", "100", "512"]', 0, 'Each cycle doubles the DNA, so after n cycles there are 2ⁿ copies: 2¹⁰ = 1024.', '{"1": "This adds two copies per cycle instead of doubling.", "2": "This multiplies 10 by 10.", "3": "512 is the number after 9 cycles."}'),
  ('BIO-7178', 'Biotechnology', 'PCR', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'Taq polymerase, from the bacterium Thermus aquaticus, is used in PCR because it', '["works only at low temperature", "can copy RNA into DNA", "does not need a primer", "is not destroyed at the high temperature (about 95 °C) used to separate DNA strands"]', 3, 'Each cycle heats the mixture to separate the strands. A heat-stable polymerase survives this, so enzyme does not need to be added again every cycle.', '{"0": "Taq polymerase works best at about 72 °C.", "1": "Copying RNA into DNA is done by reverse transcriptase.", "2": "Like other DNA polymerases, Taq needs primers."}'),
  ('BIO-7179', 'Biotechnology', 'Gel electrophoresis', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'During gel electrophoresis of DNA fragments,', '["fragments move towards the negative electrode, and larger fragments travel farther", "fragments move towards the positive electrode, and smaller fragments travel farther", "fragments move towards the positive electrode, and larger fragments travel farther", "fragments do not move because DNA has no charge"]', 1, 'Phosphate groups make DNA negatively charged, so it moves to the anode; the gel acts as a sieve, so short fragments move faster and farther.', '{"0": "DNA is negatively charged and moves to the positive electrode.", "2": "Large fragments are slowed more by the gel.", "3": "DNA carries a negative charge on each phosphate."}'),
  ('BIO-7180', 'Biotechnology', 'Monoclonal antibodies', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'In making monoclonal antibodies, antibody-producing B cells are fused with myeloma (cancer) cells because the hybrid cells', '["make one specific antibody and also divide indefinitely in culture", "make many different antibodies", "are resistant to all antigens", "do not need any nutrients"]', 0, 'B cells make the chosen antibody but die quickly in culture; myeloma cells divide endlessly. The hybridoma combines both features, producing large amounts of a single antibody.', '{"1": "Each hybridoma clone makes one antibody.", "2": "Resistance to antigens is not the aim.", "3": "Hybridomas still need culture medium."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7181', 'Biotechnology', 'DNA probes', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'A DNA probe used to diagnose a genetic disease is', '["a double-stranded plasmid carrying the normal gene", "an antibody against the faulty protein", "a restriction enzyme that cuts only the mutant gene", "a labelled single-stranded DNA sequence complementary to part of the target gene"]', 3, 'The probe base-pairs with its complementary sequence in the patient’s DNA, and its radioactive or fluorescent label shows whether the sequence is present.', '{"0": "A probe must be single-stranded to pair with the target.", "1": "Antibodies detect proteins, not DNA sequences.", "2": "Probes detect sequences by pairing, not by cutting."}'),
  ('BIO-7182', 'Biotechnology', 'Vaccines', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'The recombinant hepatitis B vaccine is made by putting the gene for the viral surface protein into yeast. It is safe because it', '["contains live, weakened hepatitis B virus", "contains ready-made antibodies", "is made from killed bacteria", "contains only the viral surface protein, with no viral genome to cause infection"]', 3, 'Yeast produces the surface antigen, which triggers antibody and memory cell production; without the viral genome, the vaccine cannot cause hepatitis.', '{"0": "The recombinant vaccine contains no virus.", "1": "Ready-made antibodies give passive immunity, not vaccination.", "2": "Hepatitis B is a virus, and the vaccine is made in yeast."}'),
  ('BIO-7183', 'Biotechnology', 'Recombinant insulin', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'To make human insulin in bacteria, the gene is usually made as cDNA from insulin mRNA using reverse transcriptase, rather than cut directly from human chromosomes. The main reason is that', '["human chromosomal DNA cannot be cut by restriction enzymes", "cDNA contains extra regulatory introns needed by bacteria", "bacteria cannot remove introns, and cDNA from mature mRNA has none", "mRNA can be inserted directly into plasmids"]', 2, 'Human genes contain introns that are spliced out of the mRNA in human cells. Bacteria lack splicing machinery, so the intron-free cDNA copy is used.', '{"0": "Human DNA can be cut by restriction enzymes.", "1": "cDNA has no introns.", "3": "Plasmids are DNA; mRNA must first be copied into DNA."}'),
  ('BIO-7184', 'Biotechnology', 'Gene therapy', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 20 Biotechnology; PMDC MDCAT 2025 Biology 16', 'Changes made by somatic cell gene therapy, such as correcting a gene in a patient’s blood cells, are not passed to the patient’s children because', '["the inserted gene is always lost within a week", "only body cells are altered, not the cells that form gametes", "the vector virus destroys the gonads", "the corrected gene is recessive"]', 1, 'Gametes come from the germ line. Somatic gene therapy alters only tissues such as lymphocytes, so the change cannot be inherited.', '{"0": "Inserted genes can persist in long-lived cells.", "2": "Vectors do not destroy the gonads.", "3": "Dominance does not stop inheritance."}'),
  ('BIO-7185', 'Evolution', 'Lamarckism', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'Weismann cut off the tails of mice for many generations, yet the offspring were always born with normal tails. This experiment was evidence against', '["natural selection", "the cell theory", "the existence of genes", "the inheritance of acquired characteristics"]', 3, 'Lamarck proposed that changes acquired during life are inherited. Weismann showed that body changes do not reach the germ cells, so they cannot be passed on.', '{"0": "Natural selection does not predict inheritance of mutilations.", "1": "The cell theory is unrelated to this experiment.", "2": "The experiment did not test the existence of genes."}'),
  ('BIO-7186', 'Evolution', 'Darwinism', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 24 Evolution; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'How would Darwin explain the long neck of the giraffe?', '["Giraffes stretched their necks and passed the longer necks to their offspring", "Giraffes with naturally longer necks survived and reproduced more, passing on the trait", "A single mutation suddenly produced long necks in all giraffes", "The environment directly changed the genes of giraffes to lengthen necks"]', 1, 'Darwin reasoned that individuals vary; those with variations that suited feeding on high leaves left more offspring, so the trait spread over many generations by natural selection.', '{"0": "Stretching and inheriting the change is Lamarck’s explanation.", "2": "Darwin stressed gradual change through many small variations.", "3": "The environment selects variations; it does not create them to order."}'),
  ('BIO-7187', 'Evolution', 'Natural selection', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 24 Evolution; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'When a population of bacteria is treated with an antibiotic, resistant bacteria soon dominate. The best explanation is that', '["the antibiotic caused the bacteria to become resistant", "bacteria learned to avoid the antibiotic", "a few resistant variants already present survived and multiplied", "all bacteria became slightly resistant by use"]', 2, 'Resistance arises by random mutation or gene transfer before the drug is used; the antibiotic kills the susceptible cells, so the resistant ones survive and reproduce.', '{"0": "The drug selects resistance; it does not create it.", "1": "Bacteria do not learn.", "3": "Resistance spreads by selection of variants, not by use."}'),
  ('BIO-7188', 'Evolution', 'Evidence of evolution', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 24 Evolution; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'The wings of a bird and the wings of an insect are', '["homologous organs, showing divergent evolution", "vestigial organs", "homologous organs, showing convergent evolution", "analogous organs, showing convergent evolution"]', 3, 'Both work for flight but have different structures and origins (bone and feathers versus cuticle), so they are analogous, produced by convergent evolution.', '{"0": "Homologous organs share structure and origin, such as the forelimbs of vertebrates.", "1": "Both are fully functional, not vestigial.", "2": "Homologous organs reflect divergent, not convergent, evolution."}'),
  ('BIO-7189', 'Evolution', 'Evidence of evolution', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 24 Evolution; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'The forelimb of a whale, the wing of a bat and the arm of a human have similar bones but different functions. They are evidence of', '["convergent evolution", "inheritance of acquired characters", "common ancestry (homologous organs and divergent evolution)", "special creation of each species"]', 2, 'The same basic pentadactyl bone plan modified for swimming, flying and grasping shows these mammals descended from a common ancestor and diverged.', '{"0": "Convergence produces similar functions from different structures.", "1": "Acquired characters are not inherited.", "3": "Shared structure points to common descent."}'),
  ('BIO-7190', 'Evolution', 'Neo-Darwinism', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 24 Evolution; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'Neo-Darwinism (the modern synthesis) improved Darwin’s theory mainly by', '["explaining that variation comes from mutation and genetic recombination", "rejecting natural selection", "showing that acquired characters are inherited", "proving that species never change"]', 0, 'Darwin could not explain where variation came from or how it was inherited; Mendelian genetics, mutation and recombination in sexual reproduction supplied the answers.', '{"1": "Natural selection remains central to neo-Darwinism.", "2": "Acquired characters are not inherited.", "3": "Neo-Darwinism explains how species change."}'),
  ('BIO-7191', 'Evolution', 'Origin of life', 'hard', 'Application beyond the PECTAA textbook text; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'In the Miller–Urey experiment, electric sparks passed through methane, ammonia, hydrogen and water vapour produced amino acids. The apparatus contained no free oxygen because', '["oxygen would stop the sparks", "oxygen was not discovered at that time", "amino acids contain no oxygen", "the early atmosphere was thought to be reducing, and oxygen would destroy the organic molecules formed"]', 3, 'The early Earth atmosphere was believed to lack free O₂; oxygen would oxidise and break down the organic compounds before they could accumulate.', '{"0": "Sparks can pass through oxygen.", "1": "Oxygen had been known since the 1770s.", "2": "Amino acids do contain oxygen in their carboxyl groups."}'),
  ('BIO-7192', 'Evolution', 'Population genetics', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 24 Evolution; PMDC MDCAT 2025 Biology 7; NUMS MDCAT 2026 Biology 8', 'In a population in Hardy–Weinberg equilibrium, 16% of individuals show a recessive phenotype. What percentage are heterozygous?', '["24%", "48%", "36%", "84%"]', 1, 'q² = 0.16, so q = 0.4 and p = 0.6. Heterozygotes = 2pq = 2 × 0.6 × 0.4 = 0.48, or 48%.', '{"0": "24% forgets to double pq.", "2": "36% is p², the homozygous dominant.", "3": "84% is all individuals with the dominant phenotype."}'),
  ('BIO-7193', 'Plant physiology', 'Transport in xylem', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 8 Plant physiology; NUMS MDCAT 2026 Biology 9.3', 'The column of water in the xylem of a tall tree does not break as transpiration pulls it upward, mainly because', '["water molecules cohere by hydrogen bonding and adhere to the xylem walls", "root pressure pushes water to the top of the tree", "xylem vessels are living cells that pump water", "the phloem pushes water into the xylem"]', 0, 'Transpiration creates tension at the leaves; cohesion between water molecules and adhesion to the narrow vessel walls let this pull be transmitted down an unbroken column (cohesion–tension theory).', '{"1": "Root pressure is too small to raise water to the top of tall trees.", "2": "Mature xylem vessels are dead, hollow tubes.", "3": "Phloem carries sugars and does not drive xylem flow."}'),
  ('BIO-7194', 'Plant physiology', 'Transport in phloem', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 8 Plant physiology; NUMS MDCAT 2026 Biology 9.3', 'According to the pressure-flow (mass flow) hypothesis, water enters the phloem sieve tubes at a source such as a leaf because', '["sucrose is actively loaded into the sieve tubes, lowering their water potential", "sucrose is removed from the sieve tubes", "the sieve tubes are dead and empty", "transpiration pulls water into the phloem"]', 0, 'Companion cells actively load sucrose into the sieve tubes; water follows by osmosis from the xylem, building up pressure that pushes the sap towards sinks where sucrose is unloaded.', '{"1": "Sucrose is removed at the sink, where water then leaves.", "2": "Sieve tubes are living cells.", "3": "Transpiration acts on the xylem, not directly on the phloem."}'),
  ('BIO-7195', 'Plant physiology', 'Stomata', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 8 Plant physiology; NUMS MDCAT 2026 Biology 9.3', 'Stomata open in the light mainly because', '["K⁺ ions move into the guard cells, water follows by osmosis and the cells become turgid", "K⁺ ions move out of the guard cells, so they become flaccid", "starch is formed from sugar in the guard cells, raising their water potential", "the guard cells lose water and shrink"]', 0, 'Light triggers proton pumping and K⁺ uptake into the guard cells; their water potential falls, water enters, and the unevenly thickened walls make them bow apart, opening the pore.', '{"1": "K⁺ leaving the guard cells closes stomata.", "2": "Converting sugar to starch would raise water potential and favour closure.", "3": "Shrinking guard cells close the pore."}'),
  ('BIO-7196', 'Plant physiology', 'Water uptake', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 8 Plant physiology; NUMS MDCAT 2026 Biology 9.3', 'The Casparian strip in the endodermis of a root blocks the movement of water through the cell walls. Its importance is that', '["water and minerals must pass through the endodermal cell membranes, which control what enters the xylem", "it speeds up water flow into the xylem", "it stores starch for the root", "it allows water to leak back from the xylem freely"]', 0, 'The suberin band seals the apoplast pathway, so everything entering the xylem must cross a selectively permeable membrane; this also lets ions be pumped in and helps create root pressure.', '{"1": "It slows apoplast flow rather than speeding it.", "2": "Starch storage is not its role.", "3": "It prevents back-leakage from the xylem."}'),
  ('BIO-7197', 'Ecology', 'Population growth', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 25 Ecology; AKU HSSC Biology', 'A population introduced into a new habitat grows slowly, then very rapidly, and finally levels off at a stable size. This S-shaped curve levels off because', '["environmental resistance limits the population at the carrying capacity", "the population stops reproducing completely", "all individuals die at the same time", "the habitat becomes unlimited"]', 0, 'Logistic growth slows as food, space and other resources run short and predation or disease increase; births and deaths balance at the carrying capacity.', '{"1": "Reproduction continues; it is balanced by deaths.", "2": "Mass death would cause a crash, not a plateau.", "3": "Unlimited resources would give J-shaped exponential growth."}'),
  ('BIO-7198', 'Ecology', 'Ecological pyramids', 'hard', 'Biology 12 (PECTAA, Punjab), Ch. 25 Ecology; AKU HSSC Biology', 'Which ecological pyramid can never be inverted?', '["Pyramid of biomass", "Pyramid of energy", "Pyramid of numbers", "Pyramid of biomass in a pond"]', 1, 'At each transfer energy is lost as heat, so less energy is available at every higher level. Numbers (one tree, many insects) and biomass (phytoplankton in water) can be inverted.', '{"0": "Biomass can be inverted, for example in aquatic ecosystems.", "2": "Numbers can be inverted, for example with one tree supporting many insects.", "3": "Aquatic biomass pyramids are often inverted."}'),
  ('BIO-7199', 'Bacteria', 'Bacterial cell wall', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; NUMS MDCAT 2026 Biology 10', 'Penicillin is generally more effective against Gram-positive than Gram-negative bacteria because', '["Gram-positive bacteria have an outer lipid membrane that absorbs penicillin", "Gram-negative bacteria have no peptidoglycan at all", "it blocks peptidoglycan cross-linking, and Gram-positive walls have a thick exposed peptidoglycan layer", "Gram-positive bacteria have no cell wall"]', 2, 'Gram-positive walls are mainly a thick peptidoglycan layer that penicillin can reach; Gram-negative bacteria have a thin peptidoglycan layer shielded by an outer membrane.', '{"0": "The outer membrane belongs to Gram-negative bacteria and blocks penicillin.", "1": "Gram-negative bacteria have a thin peptidoglycan layer.", "3": "Gram-positive bacteria have a thick wall."}'),
  ('BIO-7200', 'Bacteria', 'Endospores', 'hard', 'Biology 11 (PECTAA, Punjab), Ch. 2 Bacteria and viruses; NUMS MDCAT 2026 Biology 10', 'Surgical instruments are sterilised in an autoclave (about 121 °C under pressure) rather than in boiling water mainly because', '["bacterial endospores can survive boiling but not autoclaving", "viruses grow faster in boiling water", "boiling water dissolves the metal", "autoclaving makes the instruments sharper"]', 0, 'Endospores have a tough coat and very little water, so they resist 100 °C; steam under pressure at 121 °C for about 15 minutes kills them.', '{"1": "Viruses do not grow outside cells.", "2": "Boiling water does not dissolve surgical steel.", "3": "Sharpness is not affected."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-7201', 'Cell structure and function', 'Cell cycle', 'moderate', 'Cell cycle and cell division; AKU MBBS entrance test practice paper (Biology)', 'A cell has twice the normal (diploid) amount of DNA but shows no sign of mitosis yet. It is in', '["G₂ phase", "G₁ phase", "early S phase", "telophase"]', 0, 'DNA is copied in the S phase, so after S the cell holds double the DNA. G₂ follows, during which the cell prepares for mitosis.', '{"1": "G₁ cells have not yet copied their DNA.", "2": "In early S phase replication has only begun, so DNA is not yet doubled.", "3": "In telophase the cell is visibly dividing."}'),
  ('BIO-7202', 'Cell structure and function', 'Cell cycle', 'hard', 'Cell cycle and cell division; AKU MBBS entrance test practice paper (Biology)', 'Colchicine binds tubulin and stops microtubules forming. Dividing cells treated with colchicine are held at', '["interphase, because DNA cannot be replicated", "metaphase, because no spindle forms to separate the chromatids", "telophase, because the nuclear envelope cannot re-form", "prophase, because chromosomes cannot condense"]', 1, 'Spindle fibres are microtubules. Without them chromosomes condense but cannot be pulled apart, so cells accumulate at metaphase; this is used to prepare karyotypes.', '{"0": "DNA replication does not need microtubules.", "2": "The cells never reach telophase.", "3": "Chromosome condensation does not depend on microtubules."}'),
  ('BIO-7203', 'Cell structure and function', 'Meiosis', 'moderate', 'Cell cycle and cell division; AKU MBBS entrance test practice paper (Biology)', 'The chromosome number is halved when', '["homologous chromosomes separate in anaphase I of meiosis", "sister chromatids separate in anaphase II of meiosis", "DNA replicates in the S phase", "sister chromatids separate in mitosis"]', 0, 'In anaphase I whole homologous chromosomes go to opposite poles, so each daughter cell gets one of each pair (n). Anaphase II, like mitosis, separates chromatids and does not change the number.', '{"1": "Separating chromatids keeps the chromosome number the same.", "2": "Replication doubles DNA but not the chromosome number.", "3": "Mitosis keeps the chromosome number constant."}'),
  ('BIO-7204', 'Cell structure and function', 'Meiosis', 'hard', 'Cell cycle and cell division; AKU MBBS entrance test practice paper (Biology)', 'A human primary spermatocyte (2n = 46) completes meiosis I. Each of the two daughter cells contains', '["23 chromosomes, each made of two chromatids", "46 chromosomes, each made of one chromatid", "23 chromosomes, each made of one chromatid", "46 chromosomes, each made of two chromatids"]', 0, 'Meiosis I separates homologues, so each cell gets 23 chromosomes; the sister chromatids are still joined and separate only in meiosis II.', '{"1": "46 single chromatids is the result of mitosis.", "2": "Single-chromatid chromosomes appear only after meiosis II.", "3": "This is the state before meiosis I."}'),
  ('BIO-7205', 'Cell structure and function', 'Cell cycle', 'moderate', 'Cell cycle and cell division; AKU MBBS entrance test practice paper (Biology)', 'Human cells at metaphase of mitosis contain', '["46 chromosomes and 46 chromatids", "46 chromosomes and 92 chromatids", "23 chromosomes and 46 chromatids", "92 chromosomes and 92 chromatids"]', 1, 'All 46 chromosomes have been replicated, so each consists of two sister chromatids held at the centromere: 92 chromatids.', '{"0": "Each metaphase chromosome has two chromatids.", "2": "Mitosis does not halve the chromosome number.", "3": "The chromatids separate to become 92 chromosomes only in anaphase."}'),
  ('BIO-7206', 'Cell structure and function', 'Cell cycle', 'moderate', 'Cell cycle and cell division; AKU MBBS entrance test practice paper (Biology)', 'Cancer cells keep dividing even when crowded and when the body sends no signal to divide. This is mainly because', '["their DNA cannot be replicated", "the checkpoints that control the cell cycle no longer work", "they have no nucleus", "they divide only by meiosis"]', 1, 'Mutations in genes that control the cell cycle (such as proto-oncogenes and tumour-suppressor genes) remove the normal checks, so mitosis becomes uncontrolled and a tumour forms.', '{"0": "Cancer cells replicate their DNA repeatedly.", "2": "Cancer cells have nuclei.", "3": "Cancer cells divide by mitosis."}'),
  ('BIO-7207', 'Cell structure and function', 'Cell fractionation', 'hard', 'Cell fractionation; AKU MBBS entrance test practice paper (Biology)', 'A liver homogenate is spun in a centrifuge at increasing speeds. In which order do these components form pellets?', '["Ribosomes → microsomes → mitochondria → nuclei", "Mitochondria → nuclei → ribosomes → microsomes", "Nuclei → ribosomes → mitochondria → microsomes", "Nuclei → mitochondria → fragments of ER (microsomes) → ribosomes"]', 3, 'In differential centrifugation the largest, densest particles sediment at the lowest speed; the nucleus is largest, then mitochondria, then small membrane vesicles, and ribosomes need the highest speed.', '{"0": "This is the reverse order.", "1": "Nuclei settle before mitochondria.", "2": "Ribosomes are the smallest and settle last."}'),
  ('BIO-7208', 'Cell structure and function', 'Cell fractionation', 'moderate', 'Cell fractionation; AKU MBBS entrance test practice paper (Biology)', 'Before cell fractionation, tissue is homogenised in an ice-cold, isotonic buffer solution. The solution is isotonic so that', '["organelles neither swell and burst nor shrink by osmosis", "enzymes inside the organelles work faster", "the pH changes during centrifugation", "the organelles stick together"]', 0, 'An isotonic medium has the same water potential as the organelles, preventing osmotic damage. Cold slows enzymes that would digest the organelles, and the buffer keeps the pH steady.', '{"1": "Cold is used to slow enzymes down, not speed them up.", "2": "The buffer prevents pH changes.", "3": "The aim is to separate organelles, not clump them."}'),
  ('BIO-7209', 'Ecology', 'Ecological succession', 'moderate', 'Ecological succession; AKU MBBS entrance test practice paper (Biology)', 'Primary succession differs from secondary succession in that primary succession', '["begins after a fire in a forest where soil remains", "is always faster than secondary succession", "never reaches a climax community", "begins on bare rock or new land with no soil, and pioneer species such as lichens build up soil"]', 3, 'In primary succession there is no soil at first; lichens and mosses weather rock and add organic matter. Secondary succession starts where soil remains after disturbance, so it is faster.', '{"0": "Soil remaining after a fire means secondary succession.", "1": "Primary succession is slower because soil must form first.", "2": "Both kinds of succession can reach a climax community."}'),
  ('BIO-7210', 'Ecology', 'Ecological succession', 'easy', 'Ecological succession; AKU MBBS entrance test practice paper (Biology)', 'An abandoned farm field is colonised first by annual weeds, then grasses and shrubs, and finally trees. This is an example of', '["primary succession", "an inverted pyramid of biomass", "secondary succession", "exponential population growth"]', 2, 'The field already has soil and seeds, so the community rebuilds through stages towards a climax: this is secondary succession.', '{"0": "Primary succession starts on bare surfaces without soil.", "1": "Pyramids describe trophic levels, not community change over time.", "3": "This describes a change of communities, not one population’s growth."}'),
  ('BIO-7211', 'Biotechnology', 'Plant tissue culture', 'moderate', 'Plant tissue culture; AKU MBBS entrance test practice paper (Biology)', 'A whole plant can be grown from a single leaf cell in tissue culture. This is possible because plant cells are', '["haploid", "unable to divide once mature", "totipotent, keeping all the genes needed to form a complete plant", "free of cell walls"]', 2, 'Many plant cells keep the ability to divide and to differentiate into every cell type. On a nutrient medium with suitable hormones, an explant forms a callus that can regenerate whole plants (clones).', '{"0": "Leaf cells are diploid.", "1": "Plant cells in culture can divide again.", "3": "Plant cells have walls; protoplasts are made by removing them."}'),
  ('BIO-7212', 'Biotechnology', 'Plant tissue culture', 'hard', 'Plant tissue culture; AKU MBBS entrance test practice paper (Biology)', 'In plant tissue culture, a callus forms shoots when the medium has a high ratio of cytokinin to auxin. A high ratio of auxin to cytokinin instead promotes', '["shoot formation", "flowering only", "death of the callus", "root formation"]', 3, 'Skoog and Miller showed that the auxin : cytokinin balance controls organ formation: high cytokinin favours shoots, high auxin favours roots, and roughly equal amounts keep the callus growing undifferentiated.', '{"0": "Shoots form when cytokinin is high.", "1": "Flowering is not controlled by this ratio in callus.", "2": "The callus survives and forms roots."}'),
  ('BIO-7213', 'Biodiversity and classification', 'Algae and fungi', 'moderate', 'Algae and fungi; AKU MBBS entrance test practice paper (Biology)', 'Which pair of features distinguishes algae from fungi?', '["Algae have chitin walls; fungi have cellulose walls", "Algae store glycogen; fungi store starch", "Algae photosynthesise and have cellulose cell walls; fungi are heterotrophs with chitin cell walls", "Algae are all prokaryotes; fungi are eukaryotes"]', 2, 'Algae contain chlorophyll, make their own food and usually have cellulose walls and store starch; fungi absorb food from their surroundings, have chitin walls and store glycogen.', '{"0": "The wall materials are reversed.", "1": "The storage products are reversed.", "3": "Algae are eukaryotes; cyanobacteria are the prokaryotic photosynthesisers."}'),
  ('BIO-7214', 'Biodiversity and classification', 'Lichens', 'easy', 'Algae and fungi; AKU MBBS entrance test practice paper (Biology)', 'A lichen is a mutualistic association in which', '["the fungus photosynthesises and the alga absorbs minerals", "the alga or cyanobacterium makes food by photosynthesis, and the fungus absorbs water and minerals and gives protection", "a fungus parasitises a plant root", "a bacterium fixes nitrogen inside a legume root nodule"]', 1, 'In lichens the photosynthetic partner supplies carbohydrates, while the fungal hyphae hold water and minerals and shelter it; together they can colonise bare rock as pioneers.', '{"0": "Fungi cannot photosynthesise.", "2": "A fungus on a root in a mutualism is a mycorrhiza; parasitism is not mutualism.", "3": "Root nodules are a bacterium–plant association."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

